INSERT INTO `questions` VALUES (1,1,'Sub-suku Dayak mana yang dikenal dengan beras organik Krayan?','multiple_choice','[\"Dayak Kenyah\",\"Dayak Punan\",\"Dayak Lundayeh\",\"Dayak Kayan\"]','Dayak Lundayeh',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(2,1,'Suku Dayak Punan secara historis dikenal sebagai masyarakat?','multiple_choice','[\"Pesisir laut\",\"Penjaga hutan pedalaman (semi-nomaden)\",\"Pedagang antar pulau\",\"Petani padi sawah\"]','Penjaga hutan pedalaman (semi-nomaden)',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(3,1,'Daerah persebaran Dayak Kenyah terbesar di Kaltara berada di kabupaten?','multiple_choice','[\"Bulungan dan Malinau\",\"Tarakan dan Nunukan\",\"Tana Tidung dan Tarakan\",\"Nunukan dan Bulungan\"]','Bulungan dan Malinau',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(4,1,'Rumah panjang tradisional Suku Dayak Kenyah disebut?','multiple_choice','[\"Rumah Gadang\",\"Rumah Lamin\",\"Rumah Honai\",\"Rumah Limas\"]','Rumah Lamin',NULL,4,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(5,1,'Anting pemberat panjang adalah tradisi fisik dari suku?','multiple_choice','[\"Dayak Lundayeh\",\"Dayak Kenyah dan Kayan\",\"Dayak Punan\",\"Dayak Agabag\"]','Dayak Kenyah dan Kayan',NULL,5,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(6,2,'Lembaga adat resmi bagi Suku Dayak di Kalimantan Utara adalah?','multiple_choice','[\"Dewan Adat Dayak (DAD)\",\"Majelis Ulama Indonesia\",\"Dewan Kesenian Daerah\",\"Lembaga Adat Melayu\"]','Dewan Adat Dayak (DAD)',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(7,2,'Suku Dayak Kayan memiliki tradisi khas berupa?','multiple_choice','[\"Pembuatan kapal layar\",\"Tato (tempuling) dan ukiran kayu\",\"Menenun songket\",\"Tari Jepen\"]','Tato (tempuling) dan ukiran kayu',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(8,2,'Masyarakat agraris penghasil beras adan di Krayan adalah?','multiple_choice','[\"Dayak Punan\",\"Dayak Kenyah\",\"Dayak Lundayeh\",\"Dayak Tahol\"]','Dayak Lundayeh',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(9,2,'[HOTS - Analisis Adaptasi Ekologis] Suku Dayak Lundayeh di dataran tinggi Krayan berhasil mengembangkan sistem sawah organik menetap (padi adan), sedangkan Dayak Punan di hutan Malinau secara historis meramu dan semi-nomaden. Analisis yang paling tepat mengenai perbedaan budaya material ini adalah...','multiple_choice','[\"Kebudayaan material suku Dayak sepenuhnya ditentukan oleh pedagang luar\",\"Kearifan lokal Dayak lahir dari respons adaptif yang mendalam dan rasional terhadap karakteristik bentang alam masing-masing\",\"Suku Dayak Lundayeh memiliki teknologi yang lebih maju karena meninggalkan kepercayaan adat\",\"Suku Dayak Punan enggan menetap karena tidak memiliki ikatan emosional dengan hutan\"]','Kearifan lokal Dayak lahir dari respons adaptif yang mendalam dan rasional terhadap karakteristik bentang alam masing-masing','Pola subsistensi Dayak Lundayeh (sawah dataran tinggi) dan Punan (meramu hutan) membuktikan bahwa kearifan lokal Dayak bersifat adaptif terhadap daya dukung ekologis setempat.',4,'2026-09-21 03:28:13','2026-09-21 08:49:48'),(10,2,'[HOTS - Komparasi Kepemimpinan Antarsuku] Bandingkan struktur kepemimpinan adat Dayak di Rumah Lamin dengan sistem kepemimpinan Kesultanan pada Suku Kutai dan Banjar. Nilai filosofis kepemimpinan yang menonjol pada masyarakat Dayak adalah...','multiple_choice','[\"Kekuasaan mutlak seorang penguasa tunggal yang tidak dapat diganggu gugat\",\"Musyawarah mufakat komunal yang menjunjung tinggi kesetaraan hak antar-warga di dalam satu rumah panjang\",\"Penentuan pemimpin yang mutlak didasarkan pada kekayaan materi dan kepemilikan budak\",\"Ketergantungan kepemimpinan sepenuhnya pada restu penguasa pesisir\"]','Musyawarah mufakat komunal yang menjunjung tinggi kesetaraan hak antar-warga di dalam satu rumah panjang','Filosofi Rumah Lamin mengedepankan egaliterisme dan musyawarah mufakat komunal di bawah naungan hukum adat, berbeda dengan sistem monarki feodal kesultanan pesisir.',5,'2026-09-21 03:28:13','2026-09-21 08:49:48'),(11,3,'Kepercayaan tradisional Dayak sebelum masuknya agama samawi sering menghormati?','multiple_choice','[\"Dewa laut\",\"Roh alam dan roh leluhur\",\"Matahari dan bulan\",\"Bintang-bintang\"]','Roh alam dan roh leluhur',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(12,3,'Apa nama istilah untuk mas kawin dalam pernikahan adat Dayak Kenyah?','multiple_choice','[\"Belis\",\"Jujuran\",\"Sinamot\",\"Mahar\"]','Belis',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(13,3,'Barang apa yang sering dijadikan belis atau alat pembayaran denda adat?','multiple_choice','[\"Mobil dan rumah\",\"Gong, tempayan, dan mandau\",\"Uang koin emas\",\"Kain sutra\"]','Gong, tempayan, dan mandau',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(14,3,'Ritual adat membuka ladang dilakukan dengan tujuan?','multiple_choice','[\"Meminta izin roh tanah dan hutan\",\"Menghitung luas tanah\",\"Mencari sumber air\",\"Menghindari pajak\"]','Meminta izin roh tanah dan hutan',NULL,4,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(15,3,'Tato dalam masyarakat Dayak dianggap sebagai?','multiple_choice','[\"Hiasan tubuh semata\",\"Tanda kejahatan\",\"Peta perjalanan hidup dan status sosial\",\"Pelindung dari hujan\"]','Peta perjalanan hidup dan status sosial',NULL,5,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(16,4,'Salah satu bentuk syukuran setelah panen berhasil di kalangan Dayak disebut?','multiple_choice','[\"Nalem \\/ Pesta Panen\",\"Gawai Antu\",\"Nyepi\",\"Kasada\"]','Nalem / Pesta Panen',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(17,4,'Pemberian nama pada anak di tradisi Dayak Kenyah sering mencerminkan?','multiple_choice','[\"Bulan kelahiran\",\"Harapan atau hubungan dengan leluhur\",\"Nama pohon di sekitar\",\"Nama dewa laut\"]','Harapan atau hubungan dengan leluhur',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(18,4,'Tradisi memanjangkan daun telinga menggunakan pemberat disebut sebagai simbol?','multiple_choice','[\"Kekuatan fisik\",\"Kecantikan dan status sosial\",\"Keberanian berperang\",\"Hukuman adat\"]','Kecantikan dan status sosial',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(19,4,'[HOTS - Analisis Makna Simbolik Artefak] Dalam tradisi Dayak, tato motif \"Bunga Terung\" diukir di bagian bahu seorang pemuda. Berdasarkan perspektif filosofis kedewasaan, makna utama dari penempatan motif tersebut adalah...','multiple_choice','[\"Hiasan fisik semata agar terlihat menyeramkan di hadapan musuh\",\"Simbol kesiapan memikul beban tanggung jawab moral dan kemandirian dalam merantau menuntut ilmu hidup\",\"Tanda pelunasan denda adat terhadap kepala kampung\",\"Klaim kepemilikan mutlak atas wilayah perladangan tertentu\"]','Simbol kesiapan memikul beban tanggung jawab moral dan kemandirian dalam merantau menuntut ilmu hidup','Bahu adalah simbol pemikul beban hidup; tato bunga terung di bahu melambangkan kematangan spiritual, tanggung jawab, dan tekad merantau mencari kebijaksanaan.',4,'2026-09-21 03:28:13','2026-09-21 08:49:48'),(20,4,'[HOTS - Studi Kasus Pelestarian Budaya] Tradisi memanjangkan daun telinga menggunakan anting logam (telingaan aruu) semakin langka di kalangan generasi muda Dayak. Langkah revitalisasi budaya yang paling bijak secara akademis dan pedagogis adalah...','multiple_choice','[\"Menghapus materi tradisi telinga panjang dari kurikulum sekolah karena sudah tidak relevan\",\"Mentransformasikan nilai filosofis kesabaran dan keanggunan tradisi tersebut ke dalam karya seni rupa, ornamen busana modern, dan edukasi kontekstual\",\"Mewajibkan secara paksa seluruh siswa sekolah pedalaman untuk memanjangkan telinga\",\"Mengganti anting logam tradisional dengan aksesoris imitasi plastik impor\"]','Mentransformasikan nilai filosofis kesabaran dan keanggunan tradisi tersebut ke dalam karya seni rupa, ornamen busana modern, dan edukasi kontekstual','Pelestarian tidak selalu berarti memaksakan modifikasi fisik di era modern, melainkan mengabadikan dan mentransformasikan nilai filosofisnya ke dalam medium edukatif dan estetika kontemporer.',5,'2026-09-21 03:28:13','2026-09-21 08:49:48'),(21,5,'Alat musik petik tradisional berbentuk perahu dari suku Dayak disebut?','multiple_choice','[\"Kecapi\",\"Sape\",\"Sasando\",\"Panting\"]','Sape',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(22,5,'Sape dimainkan dengan cara?','multiple_choice','[\"Ditiup\",\"Dipukul\",\"Dipetik\",\"Digesek\"]','Dipetik',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(23,5,'Alat musik tiup dari labu kering dan pipa bambu khas Dayak disebut?','multiple_choice','[\"Suling\",\"Keluri \\/ Keledi\",\"Tifa\",\"Saluang\"]','Keluri / Keledi',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(24,5,'Ansambel gong dalam upacara adat Dayak digunakan untuk?','multiple_choice','[\"Menidurkan anak\",\"Memanggil roh, perayaan panen, dan pesta\",\"Berburu di hutan\",\"Memanggil hujan\"]','Memanggil roh, perayaan panen, dan pesta',NULL,4,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(25,5,'Sape biasanya digunakan untuk mengiringi tarian apa?','multiple_choice','[\"Tari Jepen\",\"Tari Kancet\",\"Tari Kecak\",\"Tari Piring\"]','Tari Kancet',NULL,5,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(26,6,'Suara Sape sering digambarkan seperti?','multiple_choice','[\"Gemuruh petir\",\"Angin di hutan atau aliran sungai\",\"Suara harimau\",\"Suara deru ombak\"]','Angin di hutan atau aliran sungai',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(27,6,'Gong berukuran besar dalam keluarga Dayak dianggap sebagai?','multiple_choice','[\"Benda biasa\",\"Alat komunikasi sehari-hari\",\"Benda pusaka bernilai tinggi (mas kawin\\/denda)\",\"Mainan anak-anak\"]','Benda pusaka bernilai tinggi (mas kawin/denda)',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(28,6,'Berapa jumlah senar (dawai) pada alat musik Sape tradisional?','multiple_choice','[\"1 senar\",\"3\\u20134 senar\",\"6 senar\",\"12 senar\"]','3–4 senar',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(29,6,'[HOTS - Analisis Nilai Estetika Musik] Instrumen Sape tradisional Dayak dipetik dengan melodi yang tenang, ritmis, dan meditatif di hutan Borneo. Mengapa karakter melodi Sape secara filosofis dirancang lembut dan kontemplatif saat mengiringi tarian tunggal?','multiple_choice','[\"Karena dawai Sape purba tidak dapat menghasilkan frekuensi suara berkecepatan tinggi\",\"Sebagai media ekspresi transendental untuk menghadirkan ketenangan jiwa dan keselarasan batin manusia dengan keheningan alam\",\"Agar para penonton upacara adat segera tertidur lelap\",\"Karena hukum adat Dayak melarang musik dimainkan dengan ekspresi semangat\"]','Sebagai media ekspresi transendental untuk menghadirkan ketenangan jiwa dan keselarasan batin manusia dengan keheningan alam','Petikan Sape adalah doa musikal yang merefleksikan kosmologi Dayak: keselarasan mutlak antara detak jantung manusia, hembusan angin hutan, dan dunia spiritual.',4,'2026-09-21 03:28:13','2026-09-21 08:47:12'),(30,6,'[HOTS - Komparasi Musik Etnik Kaltara] Perhatikan dua alat musik petik Kalimantan: Sape (Dayak) dan Panting (Banjar). Perbedaan karakteristik estetika dan latar belakang sosial dari kedua instrumen petik ini adalah...','multiple_choice','[\"Sape berakar dari spiritualitas alam pedalaman agraris, sedangkan Panting berkarakter riang-lincah hasil dialektika kebudayaan Melayu pesisir\",\"Sape hanya menggunakan 1 senar kawat, sedangkan Panting menggunakan dawai nilon modern\",\"Panting dimainkan untuk memanggil hujan, sedangkan Sape untuk upacara kematian raja\",\"Sape berasal dari kebudayaan Arab, sedangkan Panting dari kebudayaan Tiongkok kuno\"]','Sape berakar dari spiritualitas alam pedalaman agraris, sedangkan Panting berkarakter riang-lincah hasil dialektika kebudayaan Melayu pesisir','Sape merefleksikan kontemplasi mistik hutan pedalaman, sementara Panting Banjar mencerminkan dinamisme seni pantun dan kegembiraan komunal Melayu pesisir.',5,'2026-09-21 03:28:13','2026-09-21 08:47:12'),(31,7,'Tari Hudoq berasal dari sub-suku Dayak mana?','multiple_choice','[\"Dayak Bahau\",\"Dayak Lundayeh\",\"Dayak Punan\",\"Dayak Iban\"]','Dayak Bahau',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(32,7,'Topeng dalam Tari Hudoq menggambarkan?','multiple_choice','[\"Wajah roh-roh alam\",\"Wajah manusia biasa\",\"Pahlawan nasional\",\"Hewan ternak\"]','Wajah roh-roh alam',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(33,7,'Kostum khas penari Hudoq terbuat dari?','multiple_choice','[\"Daun kelapa\",\"Daun pisang dan rotan\",\"Kain tenun\",\"Bulu ayam\"]','Daun pisang dan rotan',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(34,7,'Apa tujuan utama Tari Hudoq?','multiple_choice','[\"Memanggil hujan besar\",\"Ritual memohon kesuburan ladang\",\"Merayakan tahun baru\",\"Menyambut kelahiran bayi\"]','Ritual memohon kesuburan ladang',NULL,4,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(35,7,'Kapan biasanya Tari Hudoq dilaksanakan?','multiple_choice','[\"Musim tanam padi\",\"Musim kemarau panjang\",\"Setiap bulan purnama\",\"Gerhana matahari\"]','Musim tanam padi',NULL,5,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(36,8,'Arti kata \"Hudoq\" dalam bahasa Dayak adalah?','multiple_choice','[\"Roh penolong\",\"Dewa pertanian\",\"Burung elang\",\"Hantu hutan\"]','Roh penolong',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(37,8,'Alat musik utama pengiring Tari Hudoq adalah?','multiple_choice','[\"Garantung (gong)\",\"Sape\",\"Gambus\",\"Rebana\"]','Garantung (gong)',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(38,8,'Gerakan mengepakkan tangan dalam Tari Hudoq terinspirasi dari burung?','multiple_choice','[\"Rajawali\",\"Enggang\",\"Merak\",\"Cendrawasih\"]','Enggang',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(39,8,'[HOTS - Studi Kasus Etika Pertunjukan] Sebuah festival pariwisata meminta penari Dayak Bahau membawakan Tari Hudoq di panggung hotel di luar musim tanam padi. Berdasarkan prinsip etika pelestarian ritual sakral, solusi kultural yang paling tepat adalah...','multiple_choice','[\"Mengubah topeng kayu sakral menjadi topeng badut komedi komersial\",\"Membedakan secara tegas antara pementasan teatrikal seni tari Hudoq sebagai atraksi budaya dengan ritual Hudoq sakral pembersihan ladang\",\"Menolak seluruh permintaan pementasan pariwisata karena budaya Dayak harus ditutup dari publik\",\"Melaksanakan penyembelihan hewan kurban di dalam lobi hotel sebelum menari\"]','Membedakan secara tegas antara pementasan teatrikal seni tari Hudoq sebagai atraksi budaya dengan ritual Hudoq sakral pembersihan ladang','Desakralisasi terkontrol melalui pembedaan seni pertunjukan (seni profan untuk edukasi/wisata) dan ritual sakral (asli di ladang) adalah strategi pelestarian yang diakui antropologi.',4,'2026-09-21 03:28:13','2026-09-21 08:49:48'),(40,8,'[HOTS - Komparasi Filosofis Tarian Kaltara] Bandingkan makna gerak Tari Hudoq (Dayak) dengan Tari Jepen (Kutai). Nilai filosofis utama yang membedakan kedua tarian representatif Kaltara ini adalah...','multiple_choice','[\"Hudoq mengekspresikan permohonan kesuburan alam lewat personifikasi roh, sedangkan Jepen mengekspresikan kesantunan pergaulan dan nilai keislaman\",\"Hudoq adalah tarian pergaulan remaja, sedangkan Jepen adalah ritual perang antar suku\",\"Hudoq ditarikan tanpa musik pengiring, sedangkan Jepen menggunakan instrumen gamelan Jawa\",\"Jepen melarang penari tersenyum, sedangkan Hudoq mengharuskan penari melepas topeng\"]','Hudoq mengekspresikan permohonan kesuburan alam lewat personifikasi roh, sedangkan Jepen mengekspresikan kesantunan pergaulan dan nilai keislaman','Hudoq berakar pada animisme-agraris perlindungan tanaman padi, sedangkan Jepen Kutai berakar pada akulturasi Melayu-Islam yang mengedepankan etika sosial dan kesantunan budi pekerti.',5,'2026-09-21 03:28:13','2026-09-21 08:47:12'),(41,9,'Hukum adat Dayak dijalankan dan dipimpin oleh?','multiple_choice','[\"Bupati\",\"Kepala Adat\",\"Polisi\",\"Ketua RT\"]','Kepala Adat',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(42,9,'Lembaga yang menaungi pelestarian adat Dayak secara formal di Kaltara adalah?','multiple_choice','[\"Dewan Perwakilan Daerah\",\"Dewan Adat Dayak (DAD)\",\"Badan Pertanahan\",\"Kementerian Kehutanan\"]','Dewan Adat Dayak (DAD)',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(43,9,'Sengketa dalam masyarakat Dayak biasanya diselesaikan melalui?','multiple_choice','[\"Pengadilan negeri\",\"Musyawarah adat\\/majelis adat\",\"Pertarungan fisik\",\"Pemungutan suara\"]','Musyawarah adat/majelis adat',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(44,9,'Tujuan utama penyelesaian konflik melalui hukum adat Dayak adalah?','multiple_choice','[\"Menghukum seberat-beratnya\",\"Pemulihan harmoni sosial dan perdamaian\",\"Mendapatkan uang denda\",\"Memenjarakan pelaku\"]','Pemulihan harmoni sosial dan perdamaian',NULL,4,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(45,9,'Konsep wilayah adat bagi Dayak berarti tanah dimiliki secara?','multiple_choice','[\"Pribadi\",\"Komunal (bersama)\",\"Negara\",\"Perusahaan\"]','Komunal (bersama)',NULL,5,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(46,10,'Hukuman dalam hukum adat Dayak umumnya berbentuk apa?','multiple_choice','[\"Kurungan penjara\",\"Denda barang berharga (babi, gong, tempayan, dll)\",\"Hukuman mati\",\"Kerja paksa\"]','Denda barang berharga (babi, gong, tempayan, dll)',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(47,10,'Apa yang terjadi setelah denda adat disepakati dan dibayar?','multiple_choice','[\"Pelaku tetap diasingkan\",\"Dilakukan ritual pemulihan hubungan \\/ perdamaian\",\"Pelaku dipenjara\",\"Masalah dibawa ke polisi\"]','Dilakukan ritual pemulihan hubungan / perdamaian',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(48,10,'Benda pusaka kuno yang sering dipakai sebagai alat bayar denda berat adalah?','multiple_choice','[\"Tempayan dan Gong\",\"Mobil\",\"Emas batangan\",\"Sertifikat tanah\"]','Tempayan dan Gong',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(49,10,'[HOTS - Studi Kasus Konservasi \"Tana Ulen\"] Konsep wilayah hutan adat \"Tana Ulen\" pada masyarakat Dayak melarang penebangan kayu komersial kecuali untuk kepentingan fasilitas umum desa atas persetujuan Lembaga Adat. Nilai modern yang paling bersesuaian dengan hukum adat ini adalah...','multiple_choice','[\"Monopoli sumber daya hutan oleh pengusaha asing\",\"Prinsip Pembangunan Berkelanjutan (Sustainable Development Goals) yang memprioritaskan konservasi keanekaragaman hayati\",\"Penolakan terhadap pembangunan infrastruktur jalan raya\",\"Penghapusan hak milik pribadi atas tanah pekarangan rumah\"]','Prinsip Pembangunan Berkelanjutan (Sustainable Development Goals) yang memprioritaskan konservasi keanekaragaman hayati','Tana Ulen adalah manifestasi hukum adat dalam menjaga daya dukung lingkungan demi keberlangsungan generasi masa depan.',4,'2026-09-21 03:28:13','2026-09-21 08:49:48'),(50,10,'[HOTS - Analisis Sosiologis Sanksi Adat \"Singker\"] Sanksi hukum adat Dayak (seperti denda tempayan kuno atau gong) dalam menyelesaikan perselisihan warga lebih berorientasi pada pemulihan keseimbangan kosmis dan kerukunan kampung. Pendekatan hukum modern apa yang identik dengan konsep ini?','multiple_choice','[\"Hukum pembalasan fisik tanpa ampun (lex talionis)\",\"Keadilan restoratif (restorative justice) yang berfokus pada rekonsiliasi dan pemulihan harmoni sosial\",\"Hukum perdata yang mengejar keuntungan finansial hakim\",\"Hukum militer darurat perang\"]','Keadilan restoratif (restorative justice) yang berfokus pada rekonsiliasi dan pemulihan harmoni sosial','Hukum adat Dayak memandang pelanggaran sebagai gangguan terhadap harmoni komunal; denda adat berfungsi menyucikan kampung dan merestorasi persaudaraan.',5,'2026-09-21 03:28:13','2026-09-21 08:49:48'),(51,11,'Senjata parang panjang khas Kalimantan disebut?','multiple_choice','[\"Keris\",\"Mandau\",\"Badik\",\"Rencong\"]','Mandau',NULL,1,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(52,11,'Gagang (Hulu) Mandau biasanya terbuat dari?','multiple_choice','[\"Besi tuang\",\"Tanduk rusa atau tulang\",\"Kaca\",\"Plastik\"]','Tanduk rusa atau tulang',NULL,2,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(53,11,'Pisau kecil pelengkap yang disisipkan di sarung Mandau bernama?','multiple_choice','[\"Pisau raut\",\"Golok\",\"Pisau dapur\",\"Belati\"]','Pisau raut',NULL,3,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(54,11,'Sarung pelindung bilah Mandau yang terbuat dari kayu berukir disebut?','multiple_choice','[\"Warangka\",\"Kumpang\",\"Selong\",\"Bungkus\"]','Kumpang',NULL,4,'2026-09-21 03:28:13','2026-09-21 03:28:13'),(55,11,'Bilah Mandau dibuat dengan teknik apa?','multiple_choice','[\"Cor (cetak)\",\"Tempa tradisional oleh Pandai Besi\",\"Las modern\",\"Pahatan batu\"]','Tempa tradisional oleh Pandai Besi',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(56,12,'Mandau Pusaka diyakini berbeda dengan Mandau harian karena?','multiple_choice','[\"Bentuknya lebih panjang\",\"Dipercaya memiliki kekuatan magis dan dijaga dengan ritual khusus\",\"Dibuat dari emas\",\"Digunakan untuk menebang pohon besar\"]','Dipercaya memiliki kekuatan magis dan dijaga dengan ritual khusus',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(57,12,'Hiasan pada hulu Mandau sering menggunakan bulu burung apa?','multiple_choice','[\"Burung Elang\",\"Burung Enggang\",\"Burung Hantu\",\"Burung Merpati\"]','Burung Enggang',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(58,12,'Sisi tajam pada bilah Mandau biasanya menghadap ke arah?','multiple_choice','[\"Lengkungan dalam\",\"Lengkungan luar\",\"Tidak ada sisi tajam\",\"Kedua sisi tajam\"]','Lengkungan luar',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(59,12,'[HOTS - Analisis Semiotika Anatomi Mandau] Mandau Dayak dilengkapi bilah baja berukir tatah emas/kuningan, hulu tanduk rusa berukir, sarung kayu (kumpang), dan pisau kecil peraut (anak mandau). Dari sudut pandang semiotika fungsional, kehadiran pisau raut membuktikan bahwa Mandau...','multiple_choice','[\"Senjata cadangan untuk melempar musuh dari kejauhan\",\"Perangkat serbaguna yang dirancang tidak hanya untuk membela diri, tetapi juga untuk menunjang aktivitas bertahan hidup dan kerajinan anyaman di rimba\",\"Hiasan tiruan tanpa kegunaan praktis\",\"Alat pemotong kuku bagi bangsawan istana\"]','Perangkat serbaguna yang dirancang tidak hanya untuk membela diri, tetapi juga untuk menunjang aktivitas bertahan hidup dan kerajinan anyaman di rimba','Pisau raut menunjukkan kecerdasan desain Dayak: Mandau besar untuk menebas semak/rotan tebal, pisau raut untuk meraut rotan halus dan mengukir.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(60,12,'[HOTS - Evaluasi Filosofis Pusaka] Mandau pusaka diperlakukan dengan penuh penghormatan dan tidak boleh ditarik dari sarungnya tanpa alasan yang sah. Pelajaran budi pekerti apa yang diwariskan dari etika senjata pusaka ini bagi generasi muda?','multiple_choice','[\"Mengajarkan rasa takut yang berlebihan terhadap benda-benda logam\",\"Pengendalian emosi tingkat tinggi bahwa kekuatan fisik dan senjata harus diimbangi dengan kedewasaan akal dan kesabaran nurani\",\"Dorongan untuk memamerkan kekebalan tubuh di tempat umum\",\"Keharusan membeli barang-barang antik berharga mahal\"]','Pengendalian emosi tingkat tinggi bahwa kekuatan fisik dan senjata harus diimbangi dengan kedewasaan akal dan kesabaran nurani','Filosofi Mandau mengajarkan: \"Jangan sekali-kali mencabut pedang jika nafsu amarah yang memegang hulunya; cabutlah hanya demi menegakkan keadilan dan membela kebenaran.\"',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(61,13,'Tarian tunggal perempuan Dayak yang lemah gemulai di atas gong disebut?','multiple_choice','[\"Kancet Ledo\",\"Datun Julut\",\"Tari Hudoq\",\"Tari Piring\"]','Kancet Ledo',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(62,13,'Tari berkelompok pria Dayak yang menunjukkan ketangkasan dan membawa perisai adalah?','multiple_choice','[\"Tari Kancet Punan Lettu\",\"Tari Serampang\",\"Tari Saman\",\"Tari Kecak\"]','Tari Kancet Punan Lettu',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(63,13,'Tari masal perempuan Dayak Kenyah yang gerakannya seperti ombak bergelombang adalah?','multiple_choice','[\"Tari Pendet\",\"Tari Datun Julut\",\"Tari Gending Sriwijaya\",\"Tari Jaipong\"]','Tari Datun Julut',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(64,13,'Rumah panjang tradisional komunal masyarakat Dayak Kenyah disebut?','multiple_choice','[\"Rumah Joglo\",\"Rumah Gadang\",\"Rumah Lamin \\/ Uma Daru\",\"Rumah Panggung Biasa\"]','Rumah Lamin / Uma Daru',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(65,13,'Salah satu alasan mengapa Rumah Lamin dibangun panjang adalah untuk?','multiple_choice','[\"Menampung seluruh anggota suku (puluhan keluarga) dalam satu atap\",\"Menyimpan hasil hutan\",\"Menjadi tempat parkir perahu\",\"Menghalangi jalan\"]','Menampung seluruh anggota suku (puluhan keluarga) dalam satu atap',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(66,14,'Dalam tarian Kancet, gerakan membentangkan tangan mencerminkan keluwesan burung apa?','multiple_choice','[\"Cendrawasih\",\"Enggang\",\"Merak\",\"Bangau\"]','Enggang',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(67,14,'Tiang-tiang Rumah Lamin biasanya dihiasi oleh?','multiple_choice','[\"Ukiran kayu dengan motif Aso dan flora khas Borneo\",\"Batu bata ekspos\",\"Kaca berwarna\",\"Cat polos saja\"]','Ukiran kayu dengan motif Aso dan flora khas Borneo',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(68,14,'Bagian teras panjang di depan kamar-kamar Rumah Lamin berfungsi untuk?','multiple_choice','[\"Dapur kotor\",\"Ruang komunal untuk berkumpul, musyawarah, dan bekerja\",\"Kandang ternak\",\"Gudang senjata\"]','Ruang komunal untuk berkumpul, musyawarah, dan bekerja',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(69,14,'[HOTS - Analisis Simbolik Gerak Tari Kancet Lasan] Tari Kancet Lasan dibawakan penari wanita Dayak Kenyah dengan menirukan gerak Burung Enggang yang terbang anggun dan bertengger di dahan pohon. Makna filosofis gerak kepakan sayap tersebut adalah...','multiple_choice','[\"Kelelahan seekor burung yang dikejar oleh pemburu\",\"Keanggunan budi pekerti wanita Dayak, kemurnian jiwa, serta kebebasan spiritual yang tetap berpijak pada perlindungan keluarga\",\"Ketidakmampuan burung untuk terbang tinggi di langit Borneo\",\"Tanda bahaya akan datangnya musuh dari seberang sungai\"]','Keanggunan budi pekerti wanita Dayak, kemurnian jiwa, serta kebebasan spiritual yang tetap berpijak pada perlindungan keluarga','Gerak Kancet Lasan menirukan Enggang (simbol kesucian alam atas): mengajarkan wanita untuk mandiri dan berbudi pekerti luhur namun tetap mengayomi rumah tangga.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(70,14,'[HOTS - Analisis Arsitektur Rumah Panggung Lamin] Arsitektur Rumah Lamin Dayak memiliki kolong panggung setinggi 3-5 meter dengan tangga masuk terbuat dari sebatang pohon utuh berukir takik (hejan). Analisis fungsi keselamatan dari konstruksi tangga hejan ini adalah...','multiple_choice','[\"Mempercepat penghuni melompat keluar saat terjadi kebakaran\",\"Dapat dibalik pada malam hari sehingga binatang buas atau musuh tidak dapat menaiki tangga masuk ke dalam rumah\",\"Sebagai sarana olahraga panjat pinang saat pesta panen\",\"Hanya berfungsi sebagai hiasan arsitektur tanpa nilai pertahanan\"]','Dapat dibalik pada malam hari sehingga binatang buas atau musuh tidak dapat menaiki tangga masuk ke dalam rumah','Tangga hejan adalah rekayasa pertahanan vernakular: saat malam atau kondisi darurat, tangga diputar/dibalik sehingga sisi bertakik berada di bawah, mencegah ancaman bahaya.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(71,15,'Motif makhluk mitologi gabungan naga dan anjing pada ukiran Dayak disebut?','multiple_choice','[\"Motif Aso\",\"Motif Garuda\",\"Motif Enggang\",\"Motif Pakis\"]','Motif Aso',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(72,15,'Warna dominan yang sangat khas pada seni manik-manik Dayak Kenyah adalah?','multiple_choice','[\"Hitam, putih, kuning, dan merah (warna alam)\",\"Merah muda dan ungu\",\"Coklat dan abu-abu\",\"Warna pastel terang\"]','Hitam, putih, kuning, dan merah (warna alam)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(73,15,'Tanaman endemik Kalimantan yang daunnya dianyam/dipintal menjadi benang kain tenun (Ulap Doyo) adalah?','multiple_choice','[\"Pandan\",\"Tanaman Doyo\",\"Rotan\",\"Bambu\"]','Tanaman Doyo',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(74,15,'Profesi pengukir ahli dalam masyarakat Dayak sering disebut dengan istilah?','multiple_choice','[\"Mangkutak\",\"Pande Besi\",\"Dalang\",\"Undagi\"]','Mangkutak',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(75,15,'Motif Sulur atau paku pakis melambangkan apa bagi orang Dayak?','multiple_choice','[\"Kematian\",\"Kesinambungan hidup dan hubungan manusia dengan alam hutan\",\"Peperangan yang panjang\",\"Air sungai\"]','Kesinambungan hidup dan hubungan manusia dengan alam hutan',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(76,16,'Selain untuk dekorasi rumah, ukiran motif Aso sering diaplikasikan pada?','multiple_choice','[\"Kertas surat\",\"Gagang Mandau, perisai, dan tameng\",\"Sepatu modern\",\"Plastik pembungkus\"]','Gagang Mandau, perisai, dan tameng',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(77,16,'Seni merangkai manik-manik (beadwork) tradisional Dayak paling ahli dilakukan oleh?','multiple_choice','[\"Pria Dayak Punan\",\"Wanita Dayak Kenyah dan Kayan\",\"Anak-anak Lundayeh\",\"Pendatang baru\"]','Wanita Dayak Kenyah dan Kayan',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(78,16,'Pembuatan baju manik-manik atau Seraung (topi khas) membutuhkan waktu?','multiple_choice','[\"Beberapa menit\",\"Beberapa hari hingga berbulan-bulan karena kerumitan polanya\",\"Satu jam\",\"Bertahun-tahun\"]','Beberapa hari hingga berbulan-bulan karena kerumitan polanya',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(79,16,'[HOTS - Analisis Filosofi Motif Sulur Pakis] Motif ukiran sulur pakis (kalung kelawit) yang melingkar tak berujung pada kerajinan anyaman rotan Dayak melambangkan...','multiple_choice','[\"Keterikatan hidup yang membuat manusia tidak bisa berkembang\",\"Siklus kesinambungan generasi, pertumbuhan hidup yang lentur menghadapi cobaan, dan persatuan komunal yang tak terputus\",\"Tanda kebingungan pengrajin dalam menentukan pola geometris\",\"Peta rahasia persembunyian harta karun di dalam gua\"]','Siklus kesinambungan generasi, pertumbuhan hidup yang lentur menghadapi cobaan, dan persatuan komunal yang tak terputus','Pakis muda melingkar dan bertumbuh membuka daun baru; sulur melambangkan regenerasi kehidupan, kelenturan adaptasi, dan keterikatan persaudaraan.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(80,16,'[HOTS - Studi Kasus Desain Komersial & Hak Kekayaan Intelektual] Banyak motif ukir Dayak Kaltara ditiru dan dicetak massal oleh industri tekstil luar negeri tanpa mencantumkan asal-usul budaya aslinya. Upaya perlindungan hukum dan budaya yang paling mendesak dilakukan adalah...','multiple_choice','[\"Melarang pengrajin lokal membuat anyaman motif tradisional\",\"Mendaftarkan motif tradisional sebagai Indikasi Geografis dan Hak Cipta Komunal di Kemenkumham serta melakukan branding sertifikasi keaslian artisanal\",\"Menuntut seluruh pabrik tekstil dunia di pengadilan internasional secara sepihak\",\"Membakar produk-produk imitasi yang beredar di pasaran lokal\"]','Mendaftarkan motif tradisional sebagai Indikasi Geografis dan Hak Cipta Komunal di Kemenkumham serta melakukan branding sertifikasi keaslian artisanal','Perlindungan warisan budaya takbenda membutuhkan instrumen Kekayaan Intelektual Komunal (KIK) agar kedaulatan motif adat diakui dan bernilai ekonomi bagi masyarakat penuturnya.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(81,17,'Suku Banjar aslinya berasal dari daerah mana?','multiple_choice','[\"Kalimantan Utara\",\"Kalimantan Timur\",\"Kalimantan Selatan\",\"Kalimantan Tengah\"]','Kalimantan Selatan',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(82,17,'Faktor utama Suku Banjar bermigrasi ke seluruh pulau Kalimantan adalah karena budaya?','multiple_choice','[\"Bertani\",\"Mencari emas\",\"Merantau (badagang\\/berdagang)\",\"Berburu hewan hutan\"]','Merantau (badagang/berdagang)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(83,17,'Agama mayoritas yang dianut oleh Suku Banjar dan sangat melekat dengan identitas budaya mereka adalah?','multiple_choice','[\"Islam\",\"Kristen\",\"Hindu\",\"Buddha\"]','Islam',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(84,17,'Rumah adat suku Banjar yang menjadi pusat kehidupan sosial keluarga besar disebut?','multiple_choice','[\"Rumah Lamin\",\"Rumah Gadang\",\"Rumah Bubungan Tinggi\",\"Rumah Betang\"]','Rumah Bubungan Tinggi',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(85,17,'Selain berdagang, keahlian masyarakat Banjar di daerah pesisir sungai Kaltara adalah?','multiple_choice','[\"Membangun perahu dan berniaga di jalur sungai\",\"Menebang pohon ulin\",\"Membuat pedang besi\",\"Bertani padi sawah terasering\"]','Membangun perahu dan berniaga di jalur sungai',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(86,18,'Kawasan sungai yang paling banyak didiami perantau Banjar di Kaltara pada masa lalu adalah di sekitar?','multiple_choice','[\"Krayan\",\"Pesisir Tarakan dan Bulungan\",\"Pedalaman Malinau\",\"Gunung Krayan\"]','Pesisir Tarakan dan Bulungan',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(87,18,'Kerajaan besar di Kalimantan Selatan yang sangat berpengaruh terhadap kebudayaan Banjar adalah Kesultanan?','multiple_choice','[\"Kutai Kartanegara\",\"Bulungan\",\"Banjar (Banjarmasin)\",\"Berau\"]','Banjar (Banjarmasin)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(88,18,'Budaya berdagang Banjar melahirkan sistem pertukaran yang khas di perairan Kalimantan yaitu?','multiple_choice','[\"Pasar Malam\",\"Pasar Terapung\",\"Pasar Senggol\",\"Mall Sungai\"]','Pasar Terapung',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(89,18,'[HOTS - Analisis Sosiologis Pemukiman Sungai Banjar] Masyarakat Suku Banjar yang bermukim di Tanjung Selor dan Tarakan secara historis membangun pemukiman bertipe Lanting di tepi sungai Kayan. Faktor pendorong utama pemilihan pola pemukiman ini adalah...','multiple_choice','[\"Larangan dari tetua adat untuk memiliki tanah di daratan kering\",\"Sungai Kayan berfungsi sebagai koridor utama logistik perdagangan hasil bumi pedalaman menuju pelabuhan laut internasional\",\"Ketidakmampuan membangun fondasi tiang di atas tanah keras\",\"Keinginan untuk selalu berpindah-pindah pulau setiap bulan\"]','Sungai Kayan berfungsi sebagai koridor utama logistik perdagangan hasil bumi pedalaman menuju pelabuhan laut internasional','Sungai Kayan adalah jalur sutra Kaltara: saudagar Banjar mendirikan lanting sebagai dermaga dagang fleksibel penampung komoditas damar, rotan, dan getah dari pedalaman Dayak.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(90,18,'[HOTS - Komparasi Nilai Kearifan Berdagang Antarsuku] Suku Banjar dikenal dengan etos kewirausahaan \"Bausaha Jujur Mencari Berkah\". Komparasikan etos perdagangan ini dengan sistem barter komoditas Suku Dayak di pedalaman. Titik temu nilai moral ekonomi dari kedua suku ini adalah...','multiple_choice','[\"Keduanya membenarkan praktik penipuan timbangan demi keuntungan materi pribadi\",\"Keduanya mendasarkan transaksi ekonomi pada prinsip kepercayaan timbal balik (trust), keadilan takaran, dan menjaga kehormatan nama baik keluarga\",\"Keduanya menolak penggunaan mata uang resmi negara\",\"Keduanya hanya berdagang dengan orang-orang yang memiliki pertalian darah sedarah\"]','Keduanya mendasarkan transaksi ekonomi pada prinsip kepercayaan timbal balik (trust), keadilan takaran, dan menjaga kehormatan nama baik keluarga','Perekonomian tradisional Kalimantan bertumpu pada hukum moral: kejujuran timbangan Banjar dan kesucian janji barter Dayak adalah modal sosial tertinggi.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(91,19,'Instrumen utama yang menghasilkan melodi pada Musik Panting terbuat dari kayu?','multiple_choice','[\"Jati\",\"Besi (Ulin)\",\"Nangka\",\"Sengon\"]','Nangka',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(92,19,'Alat musik Panting dimainkan dengan cara?','multiple_choice','[\"Ditiup\",\"Dipetik (Dawai)\",\"Dipukul keras\",\"Digesek\"]','Dipetik (Dawai)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(93,19,'Alat perkusi pelengkap dari kuningan dalam ansambel Panting disebut?','multiple_choice','[\"Babun\",\"Kendang\",\"Garantung\",\"Kangkung\"]','Kangkung',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(94,19,'Musik Panting berkembang pada era Kesultanan Banjar di abad ke?','multiple_choice','[\"Abad ke-10\",\"Abad ke-17\",\"Abad ke-21\",\"Abad ke-12\"]','Abad ke-17',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(95,19,'Musik Panting tradisional digunakan untuk mengiringi?','multiple_choice','[\"Tari perang\",\"Syair puisi Melayu (Madihin) dan cerita rakyat\",\"Pesta panen\",\"Perkelahian adat\"]','Syair puisi Melayu (Madihin) dan cerita rakyat',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(96,20,'Suara yang dihasilkan Musik Panting memiliki ritme?','multiple_choice','[\"Melankolis dan suram\",\"Lincah, dinamis dan menghibur\",\"Sangat keras dan bising\",\"Sangat lambat (langgam)\"]','Lincah, dinamis dan menghibur',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(97,20,'Gendang kecil yang berfungsi mengatur tempo (rhythm) Panting adalah?','multiple_choice','[\"Gong\",\"Babun\",\"Rebana\",\"Tifa\"]','Babun',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(98,20,'Instrumen dawai modern (pengaruh Eropa/Timur Tengah) yang kemudian diadaptasi masuk ke ansambel Panting adalah?','multiple_choice','[\"Gitar listrik\",\"Piano\",\"Biola atau Piul\",\"Terompet\"]','Biola atau Piul',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(99,20,'[HOTS - Analisis Evolusi Ensembel Panting] Pada era kontemporer, ensembel Musik Panting di Kalimantan Utara kerap memasukkan instrumen biola dan bas akustik modern tanpa mengubah tangga nada pentatonik Melayu. Analisis musikal yang tepat terhadap fenomena ini adalah...','multiple_choice','[\"Kerusakan total pakem musik tradisional akibat pengaruh budaya Barat\",\"Bentuk hibriditas musikal yang memperkaya polifoni dan warna suara melodi tanpa mengorbankan identitas melodi inti Panting\",\"Tanda bahwa instrumen panting asli sudah tidak layak dimainkan lagi\",\"Kewajiban pemerintah daerah untuk melarang penggunaan instrumen petik dawai\"]','Bentuk hibriditas musikal yang memperkaya polifoni dan warna suara melodi tanpa mengorbankan identitas melodi inti Panting','Modernisasi musik tradisi yang berhasil adalah hibriditas harmonis: instrumen gesek memperpanjang sustain nada, melengkapi petikan staccato panting yang dinamis.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(100,20,'[HOTS - Komparasi Struktur Musik Tradisional Kaltara] Bandingkan melodi Panting Banjar dengan melodi Sape Dayak. Dari aspek struktur melodi dan fungsi sosialnya, perbedaan kedua musik petik ini adalah...','multiple_choice','[\"Panting bertempo lincah dan berfungsi mengiringi tari pergaulan\\/pantun jenaka, sedangkan Sape bertempo kontemplatif dan berakar pada doa alam\\/tarian ksatria\",\"Panting tidak memiliki pola ritme ketukan, sedangkan Sape menggunakan drum elektrik\",\"Sape hanya boleh dipetik oleh wanita, sedangkan Panting hanya untuk pria\",\"Keduanya sama-sama berasal dari kebudayaan musik istana di Eropa\"]','Panting bertempo lincah dan berfungsi mengiringi tari pergaulan/pantun jenaka, sedangkan Sape bertempo kontemplatif dan berakar pada doa alam/tarian ksatria','Panting mencerminkan kegembiraan dialektika sosial Melayu Banjar, sedangkan Sape mengekspresikan kedalaman spiritual dan ketenangan kosmis belantara Borneo.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(101,21,'Kesenian Madihin dari Suku Banjar pada intinya adalah seni?','multiple_choice','[\"Tari-tarian\",\"Bertutur (pantun bersyair lisan)\",\"Seni lukis\",\"Seni pahat kayu\"]','Bertutur (pantun bersyair lisan)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(102,21,'Seorang seniman yang membawakan seni Madihin disebut?','multiple_choice','[\"Pemadihin\",\"Dalang\",\"Pesinden\",\"Mangkutak\"]','Pemadihin',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(103,21,'Alat musik perkusi khas yang dibawa dan ditabuh oleh seniman Madihin adalah?','multiple_choice','[\"Sape\",\"Gong Besar\",\"Tar \\/ Terbang (Rebana besar)\",\"Gendang panjang\"]','Tar / Terbang (Rebana besar)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(104,21,'Salah satu fungsi utama Madihin dalam masyarakat adalah untuk?','multiple_choice','[\"Berkomunikasi dengan roh leluhur\",\"Sarana dakwah agama Islam dan hiburan masyarakat\",\"Meminta hujan turun\",\"Menghukum penjahat\"]','Sarana dakwah agama Islam dan hiburan masyarakat',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(105,21,'Isi atau konten lirik Madihin biasanya bernuansa?','multiple_choice','[\"Tragedi\",\"Horor dan mistis\",\"Nasihat bijak (pepatah) yang disisipi humor\\/jenaka\",\"Sejarah peperangan mematikan\"]','Nasihat bijak (pepatah) yang disisipi humor/jenaka',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(106,22,'Kata \"Madihin\" diserap dari kata Arab \"Madah\" yang artinya?','multiple_choice','[\"Berdusta\",\"Pujian atau nasehat\",\"Menyanyi\",\"Menangis\"]','Pujian atau nasehat',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(107,22,'Pertunjukan Madihin menuntut senimannya untuk memiliki kemampuan?','multiple_choice','[\"Melukis di kanvas\",\"Bermain sulap\",\"Improvisasi lirik \\/ merangkai rima secara spontan\",\"Menyelam di sungai\"]','Improvisasi lirik / merangkai rima secara spontan',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(108,22,'Struktur syair Madihin pada umumnya menggunakan pola persajakan?','multiple_choice','[\"a-b-a-b atau a-a-a-a (pantun dan syair)\",\"Bebas tanpa rima\",\"Haiku Jepang\",\"Ghazal India\"]','a-b-a-b atau a-a-a-a (pantun dan syair)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(109,22,'[HOTS - Analisis Keterampilan Improvisasi Pamadihinan] Seorang seniman Madihin dituntut untuk mampu menciptakan bait-bait pantun berima akhir sama secara spontan di atas panggung sambil merespons tingkah laku penonton. Keterampilan berpikir tingkat tinggi apa yang paling dominan digunakan?','multiple_choice','[\"Keterampilan menghafal naskah buku cerita rakyat yang sudah baku\",\"Sintesis cepat antara observasi visual kontekstual, asosiasi kosakata berima, dan formulasi pesan moral secara spontan (spontaneous linguistic synthesis)\",\"Keahlian memainkan akrobatik gerakan tubuh di atas panggung pertunjukan\",\"Kemampuan berbicara dalam tempo lambat tanpa memperhatikan respon penonton\"]','Sintesis cepat antara observasi visual kontekstual, asosiasi kosakata berima, dan formulasi pesan moral secara spontan (spontaneous linguistic synthesis)','Madihin menuntut kecepatan pemrosesan kognitif: menangkap realitas di depan mata, menyaringnya melalui rima a-a-a-a, dan menyajikannya dalam pesan jenaka bermakna.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(110,22,'[HOTS - Studi Kasus Madihin sebagai Media Kampanye Sosial] Pemerintah Provinsi Kaltara berencana menyosialisasikan bahaya penyalahgunaan narkoba di kalangan remaja pesisir. Mengapa media seni Madihin secara pedagogis lebih efektif dibandingkan ceramah formal kaku?','multiple_choice','[\"Karena penonton Madihin diwajibkan membayar tiket masuk yang mahal\",\"Karena Madihin menyampaikan pesan persuasif melalui humor yang menghibur, bahasa santun yang tidak menggurui, dan daya pikat ritme tarbang yang memikat emosi generasi muda\",\"Karena Madihin tidak memerlukan persiapan sound system dan panggung\",\"Karena remaja Kaltara tidak menyukai kegiatan belajar mengajar\"]','Karena Madihin menyampaikan pesan persuasif melalui humor yang menghibur, bahasa santun yang tidak menggurui, dan daya pikat ritme tarbang yang memikat emosi generasi muda','Madihin memanfaatkan prinsip edutainment: pesan bahaya sosial disisipkan dalam tawa dan rima, meruntuhkan resistensi psikologis remaja terhadap nasehat kaku.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(111,23,'Kain tradisional kebanggaan Suku Banjar disebut kain?','multiple_choice','[\"Batik\",\"Sasirangan\",\"Songket\",\"Ulap Doyo\"]','Sasirangan',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(112,23,'Teknik apa yang digunakan untuk membuat pola pada kain Sasirangan?','multiple_choice','[\"Cap stempel\",\"Batik lilin (malam)\",\"Ikat celup (menjahit\\/merintang dan mewarnai)\",\"Mesin cetak tekstil\"]','Ikat celup (menjahit/merintang dan mewarnai)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(113,23,'Nama \"Sasirangan\" berasal dari kata Banjar \"Menyirang\" yang artinya?','multiple_choice','[\"Menjemur kain\",\"Mencuci baju\",\"Menjelujur (menjahit sementara) pakai benang\",\"Mencampur warna\"]','Menjelujur (menjahit sementara) pakai benang',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(114,23,'Pada zaman dahulu, kain Sasirangan dikenal sebagai kain \"Pamintaan\" yang dipercaya dapat?','multiple_choice','[\"Mendatangkan hujan\",\"Dipakai sebagai obat atau pengusir penyakit (magis)\",\"Membuat kebal senjata\",\"Menangkap ikan\"]','Dipakai sebagai obat atau pengusir penyakit (magis)',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(115,23,'Motif Sasirangan yang menyerupai ombak disebut motif?','multiple_choice','[\"Gigi Haruan (Gigi Ikan Gabus)\",\"Ombak Sinapur Karang\",\"Naga Balimbur\",\"Bayem Raja\"]','Ombak Sinapur Karang',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(116,24,'Motif tajam seperti segitiga berjajar (gigi) pada Sasirangan yang terinspirasi dari ikan predator sungai adalah?','multiple_choice','[\"Gigi Hiu\",\"Gigi Haruan (Gigi ikan gabus)\",\"Gigi Buaya\",\"Gigi Piranha\"]','Gigi Haruan (Gigi ikan gabus)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(117,24,'Warna kuning pada kain Sasirangan zaman dahulu, selain dari kunyit, secara magis melambangkan diperuntukkan bagi?','multiple_choice','[\"Kaum tani\",\"Pengobatan penyakit kuning (penyakit hati)\",\"Perang\",\"Penyakit mata\"]','Pengobatan penyakit kuning (penyakit hati)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(118,24,'Langkah pertama membuat Sasirangan setelah mendesain motif di atas kain adalah?','multiple_choice','[\"Mencelup warna merah\",\"Menjahit jelujur pada pola lalu ditarik erat (disirang)\",\"Langsung dijemur matahari\",\"Disetrika panas\"]','Menjahit jelujur pada pola lalu ditarik erat (disirang)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(119,24,'[HOTS - Analisis Kimiawi & Lingkungan Pewarnaan Alami] Pada masa lampau, perajin Sasirangan menggunakan kunyit (kuning), daun nila (biru), dan kulit kayu ulin (cokelat tua) sebagai bahan pewarna alami. Ditinjau dari prinsip kimia hijau dan ekologi modern, keunggulan pewarna alami ini adalah...','multiple_choice','[\"Warna kain langsung luntur dalam satu kali pencucian air tawar\",\"Limbah residu pencelupan bersifat biodegradable (mudah terurai tanah), tidak mencemari ekosistem sungai, dan aman bagi kesehatan kulit pemakainya\",\"Waktu proses pencelupan jauh lebih singkat dibandingkan pewarna sintetis buatan pabrik\",\"Mengharuskan penggunaan bahan pengawet merkuri berbahaya\"]','Limbah residu pencelupan bersifat biodegradable (mudah terurai tanah), tidak mencemari ekosistem sungai, dan aman bagi kesehatan kulit pemakainya','Kearifan pewarna nabati Sasirangan adalah teladan produksi tekstil berkelanjutan: limbah sisa pewarna ramah bagi mikroorganisme tanah dan sungai.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(120,24,'[HOTS - Analisis Nilai Simbolis Motif Naga Balimbur] Motif Sasirangan \"Naga Balimbur\" melambangkan naga yang mandi di sungai pada pagi hari yang cerah. Berdasarkan interpretasi filosofis masyarakat Banjar, motif ini secara simbolik digunakan pada selendang pengantin dengan harapan...','multiple_choice','[\"Agar pengantin ditakuti oleh seluruh warga kampung karena memiliki kekuatan naga\",\"Pembersihan jiwa dari aura negatif, limpahan kegembiraan baru dalam membina bahtera rumah tangga, dan kemakmuran hidup bagaikan air mengalir\",\"Tanda bahwa pengantin berasal dari keturunan pawang binatang buas\",\"Simbol larangan bagi pengantin untuk mendekati tepian sungai\"]','Pembersihan jiwa dari aura negatif, limpahan kegembiraan baru dalam membina bahtera rumah tangga, dan kemakmuran hidup bagaikan air mengalir','Naga Balimbur (naga mandi) adalah simbol kesegaran rohani dan berkah kesuburan air: pengantin disucikan menyongsong kehidupan baru yang penuh kelimpahan rezeki.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(121,25,'Bangunan rumah adat paling ikonik peninggalan Kesultanan Banjar disebut?','multiple_choice','[\"Rumah Bubungan Tinggi\",\"Rumah Lamin\",\"Rumah Lanting\",\"Rumah Joglo\"]','Rumah Bubungan Tinggi',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(122,25,'Bagian paling mencolok dari Rumah Bubungan Tinggi adalah?','multiple_choice','[\"Teras sangat panjang\",\"Atap tengah yang sangat lancip (curam) ke atas\",\"Tiang pendek menyentuh tanah\",\"Tidak memiliki atap\"]','Atap tengah yang sangat lancip (curam) ke atas',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(123,25,'Material utama yang digunakan membangun rumah adat ini adalah?','multiple_choice','[\"Bambu kuning\",\"Kayu Ulin (kayu besi)\",\"Batu bata\",\"Papan triplek\"]','Kayu Ulin (kayu besi)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(124,25,'Selain adaptasi cuaca, mengapa Rumah Bubungan Tinggi berbentuk panggung tinggi?','multiple_choice','[\"Karena wilayah rawan gempa\",\"Agar aman dari luapan banjir\\/pasang surut sungai dan serangan hewan buas\",\"Untuk gudang mobil\",\"Karena diwajibkan oleh sultan\"]','Agar aman dari luapan banjir/pasang surut sungai dan serangan hewan buas',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(125,25,'Ornamen ukiran kayu silang di ujung atap Rumah Bubungan Tinggi melambangkan kepala burung Enggang atau naga yang disebut?','multiple_choice','[\"Kubah emas\",\"Sungkul \\/ Jamang\",\"Tali angin\",\"Sirap\"]','Sungkul / Jamang',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(126,26,'Tingkat kemiringan atap tengah yang sangat curam (bubungan) bertujuan untuk?','multiple_choice','[\"Mengusir roh jahat\",\"Mempercepat turunnya air hujan agar atap tidak lapuk\",\"Menyimpan padi di atap\",\"Mengintai musuh\"]','Mempercepat turunnya air hujan agar atap tidak lapuk',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(127,26,'Ruang tamu depan terbuka di Rumah Bubungan Tinggi disebut?','multiple_choice','[\"Palatar\",\"Panampik\",\"Bilik\",\"Dapur\"]','Palatar',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(128,26,'Pintu masuk ke dalam rumah utama sering dikelilingi oleh ukiran tumbuhan dan bunga yang disebut ukiran?','multiple_choice','[\"Motif floral Banjar\",\"Motif Aso\",\"Motif Parang\",\"Motif Cakar\"]','Motif floral Banjar',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(129,26,'[HOTS - Analisis Struktur Zona Privat & Publik] Rumah Bubungan Tinggi memiliki tangga berundak menuju pelataran (surambi), ruang tamu (panampik basar), hingga ruang privat tidur (palidangan/anjung). Pembagian zonasi berundak ini secara sosiologis mencerminkan...','multiple_choice','[\"Kesulitan tukang kayu dalam meratakan permukaan lantai rumah\",\"Kecerdasan tata krama kesopanan di mana privasi keluarga kehormatan wanita terlindungi di ruang anjung atas, sementara interaksi publik dibatasi di surambi depan\",\"Larangan bagi anak-anak untuk menginjakkan kaki di lantai rumah\",\"Tanda bahwa rumah tersebut sering terendam air bah setinggi atap\"]','Kecerdasan tata krama kesopanan di mana privasi keluarga kehormatan wanita terlindungi di ruang anjung atas, sementara interaksi publik dibatasi di surambi depan','Tingkat elevasi lantai Rumah Banjar adalah peta etika sosial: semakin ke dalam dan semakin tinggi lantai, semakin privat dan sakral fungsi ruangannya.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(130,26,'[HOTS - Analisis Ketahanan Material Kayu Ulin] Mengapa tiang pancang Rumah Bubungan Tinggi Banjar dan Rumah Baloy Tidung tidak mengalami pelapukan meskipun terendam air rawa gambut dan pasang surut air asin selama ratusan tahun?','multiple_choice','[\"Karena kayu ulin dilapisi cat plastik sintetis anti-air modern\",\"Struktur sel kayu ulin (Eusideroxylon zwageri) memiliki kerapatan serat ekstrem dan kandungan silika\\/zat ekstraktif alami yang justru semakin mengeras dan membatu saat terkena air\",\"Karena air rawa Kalimantan tidak mengandung bakteri pengurai\",\"Karena tiang rumah selalu diganti setiap enam bulan sekali\"]','Struktur sel kayu ulin (Eusideroxylon zwageri) memiliki kerapatan serat ekstrem dan kandungan silika/zat ekstraktif alami yang justru semakin mengeras dan membatu saat terkena air','Kayu ulin adalah \"ironwood\" tropis: senyawa ekstraktif tanin dan silikanya membentuk lapisan anti-rayap dan anti-pembusukan alami yang tahan oksidasi air.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(131,27,'Masakan berkuah kaldu ayam khas suku Banjar yang paling terkenal secara nasional adalah?','multiple_choice','[\"Coto Makassar\",\"Soto Banjar\",\"Soto Lamongan\",\"Soto Betawi\"]','Soto Banjar',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(132,27,'Bumbu rempah yang membuat kaldu Soto Banjar sangat wangi dan sedikit menyerupai masakan Arab/Timur Tengah adalah?','multiple_choice','[\"Bawang putih saja\",\"Kapulaga, Cengkeh, Kayu Manis, dan Pala\",\"Cabai dan tomat\",\"Lengkuas merah\"]','Kapulaga, Cengkeh, Kayu Manis, dan Pala',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(133,27,'Makanan pendamping utama pengganti nasi putih saat makan Soto Banjar adalah?','multiple_choice','[\"Singkong rebus\",\"Ketupat\",\"Roti tawar\",\"Mie kuning besar\"]','Ketupat',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(134,27,'Ikan air tawar predator (ikan gabus) yang menjadi lauk favorit dan kebanggaan Banjar adalah ikan?','multiple_choice','[\"Lele\",\"Haruan\",\"Nila\",\"Patin\"]','Haruan',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(135,27,'Kue tradisional manis (Wadai) Banjar yang berbentuk lingkaran lapis-lapis dan sangat lembut disebut?','multiple_choice','[\"Bingka\",\"Lapis legit\",\"Kue pukis\",\"Kue putu\"]','Bingka',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(136,28,'Soto Banjar memiliki warna kuah kaldu agak keruh dan kental karena dicampur dengan bahan pengental khusus yaitu?','multiple_choice','[\"Santan kelapa tebal\",\"Susu cair atau kuning telur bebek\",\"Tepung beras putih\",\"Kecap manis\"]','Susu cair atau kuning telur bebek',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(137,28,'Masakan ikan Patin atau Haruan dengan bumbu kuning kemerahan rasa asam manis khas Banjar disebut?','multiple_choice','[\"Ikan bakar\",\"Gangan Asam (Sayur Asam) Ikan\",\"Pepes ikan\",\"Ikan goreng tepung\"]','Gangan Asam (Sayur Asam) Ikan',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(138,28,'Ikan panggang khas Banjar biasanya selalu diolesi bumbu dasar yang kuat aroma?','multiple_choice','[\"Lada hitam\",\"Terasi, asam jawa, dan kemiri\",\"Keju\",\"Mayones\"]','Terasi, asam jawa, dan kemiri',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(139,28,'[HOTS - Analisis Sains Pangan Pembuatan Ketupat Kandangan/Soto] Dalam tradisi kuliner Banjar, beras untuk ketupat dimasak di dalam anyaman daun kelapa muda (janur) selama berjam-jam. Fungsi biokimia dan organoleptik dari rebusan janur kelapa tersebut adalah...','multiple_choice','[\"Membuat beras menjadi keras dan tidak dapat dikunyah\",\"Zat tanin alami dari janur kelapa memberikan aroma wangi khas, mengenyalkan tekstur pati beras, sekaligus bertindak sebagai pengawet alami tanpa bahan kimia\",\"Menghilangkan seluruh kandungan karbohidrat dari beras\",\"Agar warna ketupat menjadi merah menyala\"]','Zat tanin alami dari janur kelapa memberikan aroma wangi khas, mengenyalkan tekstur pati beras, sekaligus bertindak sebagai pengawet alami tanpa bahan kimia','Janur kelapa melepaskan senyawa fenolik dan tanin alami saat direbus lama; zat ini menghambat pembusukan mikroba dan mengikat amilosa beras menjadi kenyal pulen.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(140,28,'[HOTS - Studi Kasus Diversifikasi Pangan Tradisional] Kue tradisional Banjar seperti \"Bingka Barandam\" dan \"Amparan Tatak\" menggunakan pisang talas dan santan kelapa lokal. Gagasan modifikasi produk yang tepat untuk penderita diabetes tanpa menghilangkan cita rasa tradisional adalah...','multiple_choice','[\"Mengganti seluruh tepung beras dengan serbuk kayu manis murni\",\"Mensubstitusi gula pasir berlebih dengan pemanis alami berindeks glikemik rendah (seperti gula kelapa\\/stevia) dan mempertahankan teknik kukus tradisional\",\"Menggoreng kue bingka dalam minyak jelantah bersuhu tinggi\",\"Melarang masyarakat lansia mengonsumsi makanan tradisional sama sekali\"]','Mensubstitusi gula pasir berlebih dengan pemanis alami berindeks glikemik rendah (seperti gula kelapa/stevia) dan mempertahankan teknik kukus tradisional','Inovasi gastronomi sehat mengharuskan pemahaman formula gizi: menjaga kelembutan tekstur santan kukus tradisional sambil merekayasa sumber pemanis yang ramah metabolik.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(141,29,'Upacara tradisional Banjar bagi anak atau calon pengantin yang telah tamat mengaji Al-Quran disebut upacara?','multiple_choice','[\"Batamat Al-Quran\",\"Bawalah\",\"Balimau\",\"Tepung Tawar\"]','Batamat Al-Quran',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(142,29,'Batamat Al-Quran biasanya dilangsungkan berbarengan dengan acara besar keluarga yaitu?','multiple_choice','[\"Pesta panen padi\",\"Acara Resepsi Pernikahan (Pengantin Banjar)\",\"Pemakaman massal\",\"Tahun baru hijriah\"]','Acara Resepsi Pernikahan (Pengantin Banjar)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(143,29,'Payung hias meriah bermotif warna-warni (merah/kuning) yang dibawa selama arak-arakan Batamat disebut?','multiple_choice','[\"Payung ubur-ubur\",\"Payung Ubur-ubur \\/ Payung Kertas Banjar\",\"Payung terjun\",\"Payung hitam\"]','Payung Ubur-ubur / Payung Kertas Banjar',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(144,29,'Alat musik tradisional yang bertalu-talu mengiringi arak-arakan khataman Al-Quran ini adalah?','multiple_choice','[\"Gitar listrik\",\"Sinoman Hadrah (Terbang\\/Rebana besar)\",\"Piano klasik\",\"Seruling bambu\"]','Sinoman Hadrah (Terbang/Rebana besar)',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(145,29,'Makanan atau kue simbolis berbentuk kerucut ketan khas yang disajikan untuk dibagikan saat syukuran Batamat disebut?','multiple_choice','[\"Nasi tumpeng ketan (Nasi Astakona\\/Balai)\",\"Kue tar besar\",\"Roti buaya\",\"Lemper raksasa\"]','Nasi tumpeng ketan (Nasi Astakona/Balai)',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(146,30,'Apa tujuan dan nilai moral utama dari pelaksanaan upacara Batamat Al-Quran?','multiple_choice','[\"Menghabiskan harta keluarga\",\"Rasa syukur dan pengingat bahwa calon pengantin\\/anak telah dibekali ilmu agama sebagai pedoman hidup\",\"Unjuk kekayaan kepada tetangga\",\"Sebagai hiburan malam hari\"]','Rasa syukur dan pengingat bahwa calon pengantin/anak telah dibekali ilmu agama sebagai pedoman hidup',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(147,30,'Dalam prosesi Batamat, sang anak/pengantin akan membaca surah-surah pendek juz ke berapa dari Al-Quran?','multiple_choice','[\"Juz 1\",\"Juz 30 (Amma)\",\"Seluruh Al-Quran 30 Juz saat acara\",\"Tidak membaca, hanya duduk\"]','Juz 30 (Amma)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(148,30,'Ornamen khas Batamat yang dibuat dari bambu dihiasi bendera kertas atau uang kertas (Pohon Uang) untuk diperebutkan disebut?','multiple_choice','[\"Pohon beringin\",\"Pohon kembang \\/ Payung Kembang Uang\",\"Pohon kurma\",\"Bunga mawar palsu\"]','Pohon kembang / Payung Kembang Uang',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(149,30,'[HOTS - Analisis Nilai Edukatif Upacara Batamat] Tradisi \"Batamat Al-Qur\'an\" diselenggarakan meriah dengan arak-arakan payung kembang saat seorang anak berhasil menuntaskan bacaan 30 juz Al-Qur\'an. Nilai psikologi pendidikan (reinforcement) yang terkandung dalam perayaan adat ini adalah...','multiple_choice','[\"Menumbuhkan rasa sombong pada diri anak di hadapan teman sebayanya\",\"Memberikan apresiasi sosial dan penguatan positif agar anak mencintai literasi kitab suci serta memotivasi anak-anak lain untuk tekun menuntut ilmu agama\",\"Menghabiskan tabungan keluarga demi pesta kemewahan duniawi\",\"Tanda bahwa anak tersebut tidak perlu lagi belajar seumur hidupnya\"]','Memberikan apresiasi sosial dan penguatan positif agar anak mencintai literasi kitab suci serta memotivasi anak-anak lain untuk tekun menuntut ilmu agama','Batamat adalah bentuk kearifan parenting komunal: merayakan pencapaian spiritual anak dengan kemuliaan kultural agar ilmu agama tertanam sebagai kebanggaan sejati.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(150,30,'[HOTS - Komparasi Ritus Inisiasi Kedewasaan Antarsuku] Bandingkan tradisi Batamat Al-Qur\'an (Banjar) dengan Tradisi Mengukir Tato Bunga Terung (Dayak). Persamaan hakiki dari kedua ritus budaya yang berbeda latar belakang religi ini adalah...','multiple_choice','[\"Keduanya merupakan penanda transisi tahapan usia (rites of passage) dari masa kanak-kanak menuju tanggung jawab kedewasaan moral dan sosial di hadapan komunitasnya\",\"Keduanya mengharuskan anak menjalani puasa bicara selama satu tahun penuh\",\"Kedua tradisi sama-sama diimpor dari kebudayaan bangsa Eropa abad ke-18\",\"Keduanya bertujuan untuk menentukan calon jodoh sejak usia balita\"]','Keduanya merupakan penanda transisi tahapan usia (rites of passage) dari masa kanak-kanak menuju tanggung jawab kedewasaan moral dan sosial di hadapan komunitasnya','Dalam antropologi, keduanya adalah \"rites of passage\": mengakui secara sah bahwa sang individu telah lulus ujian etika dan siap memikul tanggung jawab moral kampung.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(151,31,'Rumah tradisional Suku Banjar yang dibangun terapung mengapung di atas sungai (dirakit di atas batang kayu besar) dinamakan rumah?','multiple_choice','[\"Rumah Panggung\",\"Rumah Lanting\",\"Rumah Bubungan Tinggi\",\"Rumah Kaca\"]','Rumah Lanting',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(152,31,'Batang kayu raksasa penyangga Rumah Lanting di bawah air agar mengapung tidak tenggelam adalah?','multiple_choice','[\"Batang pisang\",\"Batang Pohon Binuang atau Ulin besar utuh\",\"Drum plastik\",\"Semen beton\"]','Batang Pohon Binuang atau Ulin besar utuh',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(153,31,'Pasar tradisional masyarakat Banjar yang aktivitas jual belinya dilakukan sepenuhnya dari atas perahu klotok di sungai disebut?','multiple_choice','[\"Pasar Kaget\",\"Pasar Terapung\",\"Pasar Malam\",\"Pasar Senggol\"]','Pasar Terapung',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(154,31,'Perahu kecil (sampan) bermesin tempel di buritan, yang bunyinya tok-tok-tok khas perairan sungai Kalimantan dinamakan perahu?','multiple_choice','[\"Kapal Feri\",\"Klotok\",\"Yacht\",\"Kapal induk\"]','Klotok',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(155,31,'Perempuan-perempuan Banjar pedagang di pasar terapung biasanya mengenakan pelindung kepala dari panas berupa topi anyam yang disebut?','multiple_choice','[\"Topi Koboi\",\"Tanggui\",\"Peci \\/ Kopiah\",\"Helm motor\"]','Tanggui',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(156,32,'Apa alasan utama suku Banjar lampau sering membangun rumah Lanting (terapung)?','multiple_choice','[\"Agar tidak bayar pajak tanah dan mudah berpindah mengikuti sumber rezeki sungai\",\"Karena takut tanah longsor di gunung\",\"Untuk berperang\",\"Karena larangan raja membangun di darat\"]','Agar tidak bayar pajak tanah dan mudah berpindah mengikuti sumber rezeki sungai',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(157,32,'Kehidupan berpusat pada sungai menjadikan masyarakat Banjar memiliki julukan sebagai manusia?','multiple_choice','[\"Manusia Daratan\",\"Urang Banyu (Masyarakat Air \\/ Sungai)\",\"Manusia Gunung\",\"Orang Laut Lepas\"]','Urang Banyu (Masyarakat Air / Sungai)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(158,32,'Topi Tanggui khas Banjar (terendak lebar) umumnya dibuat dari anyaman bahan alam, yaitu?','multiple_choice','[\"Plastik sintetis\",\"Daun nipah atau pandan yang dianyam rapat\",\"Besi alumunium\",\"Kulit sapi kering\"]','Daun nipah atau pandan yang dianyam rapat',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(159,32,'[HOTS - Analisis Kearifan Ekologis Pasar Terapung] Aktivitas jual beli di atas perahu kelotok/jukung pada pasar terapung Banjar menggunakan koin atau sistem tukar hasil bumi tanpa mendirikan bangunan beton di atas air. Keunggulan ekologis dari tradisi pasar terapung ini adalah...','multiple_choice','[\"Membatasi jumlah barang dagangan yang dapat dijual kepada masyarakat\",\"Mencegah sedimentasi dan kerusakan sempadan sungai karena tidak memerlukan pembabatan tanaman bakau\\/rawa untuk fondasi ruko beton\",\"Membuat air sungai menjadi lebih keruh dan berlumpur\",\"Menghindari kewajiban membayar pajak retribusi daerah\"]','Mencegah sedimentasi dan kerusakan sempadan sungai karena tidak memerlukan pembabatan tanaman bakau/rawa untuk fondasi ruko beton','Pasar terapung adalah model ekonomi sirkular ramah riparian: sungai tetap mengalir alami tanpa tercekik tiang fondasi beton permanen di sempadan air.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(160,32,'[HOTS - Pemecahan Masalah Eksistensi Budaya Sungai di Era Darat] Seiring dibukanya jalan raya darat dan jembatan beton di Kalimantan Utara, aktivitas pasar sungai dan rumah lanting mulai ditinggalkan. Strategi revitalisasi yang paling bernilai ekonomi kreatif adalah...','multiple_choice','[\"Menghancurkan seluruh jembatan darat agar masyarakat kembali menggunakan perahu\",\"Mengonversi pasar terapung menjadi destinasi wisata budaya berbasis ekowisata perairan yang terintegrasi dengan kuliner terapung dan penjualan kerajinan lokal\",\"Melarang warga membeli kendaraan bermotor roda dua\",\"Menimbun sungai-sungai kecil menjadi jalan aspal perkotaan\"]','Mengonversi pasar terapung menjadi destinasi wisata budaya berbasis ekowisata perairan yang terintegrasi dengan kuliner terapung dan penjualan kerajinan lokal','Pergeseran fungsi dari pasar logistik murni menjadi daya tarik pariwisata heritage adalah strategi global yang menyelamatkan lanskap budaya sungai dari kepunahan.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(161,33,'Kerajaan Kutai Martadipura diakui sebagai kerajaan bercorak apa yang tertua di Nusantara?','multiple_choice','[\"Kerajaan Islam\",\"Kerajaan Hindu\",\"Kerajaan Buddha\",\"Kerajaan Kristen\"]','Kerajaan Hindu',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(162,33,'Bukti sejarah peninggalan Kerajaan Kutai berupa tiang batu bertuliskan huruf Pallawa disebut?','multiple_choice','[\"Prasasti Yupa\",\"Prasasti Kedukan Bukit\",\"Candi Borobudur\",\"Arca Ganesha\"]','Prasasti Yupa',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(163,33,'Raja terkenal dari Kerajaan Kutai Martadipura yang memberikan sedekah 20.000 ekor sapi kepada kaum Brahmana adalah?','multiple_choice','[\"Raja Kudungga\",\"Raja Mulawarman\",\"Raja Aswawarman\",\"Raja Hayam Wuruk\"]','Raja Mulawarman',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(164,33,'Lokasi pusat kerajaan Kutai kuno terletak di daerah hulu sungai apa di Kalimantan?','multiple_choice','[\"Sungai Kapuas\",\"Sungai Barito\",\"Sungai Mahakam\",\"Sungai Kayan\"]','Sungai Mahakam',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(165,33,'Suku Kutai asli secara historis terbentuk dari asimilasi antara penduduk asli pedalaman (Dayak) dengan?','multiple_choice','[\"Pendatang Eropa\",\"Pedagang Melayu dan India\",\"Tentara Jepang\",\"Penjajah Belanda\"]','Pedagang Melayu dan India',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(166,34,'Kerajaan Kutai Kartanegara (bercorak Islam) akhirnya menaklukkan Kutai Martadipura. Siapakah pendiri Kutai Kartanegara?','multiple_choice','[\"Aji Batara Agung Dewa Sakti\",\"Sultan Hasanuddin\",\"Raja Mulawarman\",\"Gajah Mada\"]','Aji Batara Agung Dewa Sakti',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(167,34,'Bahasa Kutai yang digunakan oleh masyarakat terbagi menjadi beberapa dialek. Salah satu dialek yang paling umum adalah?','multiple_choice','[\"Dialek Tenggarong\",\"Dialek Banjarmasin\",\"Dialek Tarakan\",\"Dialek Nunukan\"]','Dialek Tenggarong',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(168,34,'Prasasti Yupa menggunakan bahasa kuno, yaitu?','multiple_choice','[\"Bahasa Indonesia\",\"Bahasa Melayu Kuno\",\"Bahasa Sansekerta\",\"Bahasa Arab\"]','Bahasa Sansekerta',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(169,34,'[HOTS - Analisis Konseptual Prasasti Yupa] Prasasti Yupa menyebutkan istilah \"Vaprakecvara\" (lapangan suci tempat pemujaan Siwa) dan upacara \"Vratyastoma\" bagi Raja Mulawarman. Analisis historis yang tepat mengenai penguasaan ritual keagamaan ini adalah...','multiple_choice','[\"Masyarakat Kutai kuno dijajah dan dipaksa memeluk agama dari India\",\"Raja-raja lokal Kutai secara mandiri dan cerdas mengadopsi konsep ketatanegaraan dan agama Hindu untuk melegitimasi kedaulatan politik kerajaannya tanpa kehilangan kepribadian lokal\",\"Kerajaan Kutai tidak memiliki peradaban asli sebelum kedatangan bangsa asing\",\"Prasasti Yupa ditulis oleh wisatawan yang kebetulan singgah di Kalimantan\"]','Raja-raja lokal Kutai secara mandiri dan cerdas mengadopsi konsep ketatanegaraan dan agama Hindu untuk melegitimasi kedaulatan politik kerajaannya tanpa kehilangan kepribadian lokal','Teori Arus Balik membuktikan kehebatan diplomasi Kutai: penguasa lokal berinisiatif mengundang brahmana untuk ritual kenegaraan yang mengukuhkan posisi Kutai di peta dunia.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(170,34,'[HOTS - Analisis Dampak Aliran Sungai Mahakam ke Kaltara] Hubungan historis dan kultural antara Suku Kutai di Kalimantan Timur dengan wilayah Kalimantan Utara (Bulungan dan Nunukan) terjalin melalui...','multiple_choice','[\"Peperangan saudara yang menghancurkan seluruh desa di perbatasan\",\"Jaringan diplomasi perdagangan maritim muara sungai, kesamaan akar rumpun bahasa Melayu Barito-Kutai, dan ikatan perkawinan antar-keluarga bangsawan istana\",\"Pembangunan benteng militer pemisah di sepanjang perbatasan provinsi\",\"Kewajiban upeti paksa yang memiskinkan rakyat jelata\"]','Jaringan diplomasi perdagangan maritim muara sungai, kesamaan akar rumpun bahasa Melayu Barito-Kutai, dan ikatan perkawinan antar-keluarga bangsawan istana','Batas provinsi administratif modern tidak memutus persaudaraan kultural: Kutai dan Kaltara terhubung oleh dialektika sungai-pantai dan rumpun kebudayaan Melayu Kalimantan.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(171,35,'Tari Jepen merupakan kesenian tari tradisional yang identik dengan suku?','multiple_choice','[\"Dayak\",\"Banjar\",\"Kutai\",\"Tidung\"]','Kutai',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(172,35,'Nama \"Jepen\" diperkirakan diserap dari kata bahasa Arab atau tarian pesisir Melayu kuno yaitu?','multiple_choice','[\"Jaipong\",\"Japin atau Zapin\",\"Jathilan\",\"Joged\"]','Japin atau Zapin',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(173,35,'Gerakan Tari Jepen sangat kental didominasi oleh unsur yang bersifat?','multiple_choice','[\"Agresif dan keras\",\"Lembut, anggun, dan lincah kaki\",\"Patah-patah tajam\",\"Melompat-lompat tinggi (akrobat)\"]','Lembut, anggun, dan lincah kaki',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(174,35,'Kostum penari Jepen wanita Kutai menggunakan balutan kain warna-warni mengkilap serta memakai sanggul rambut berhias bunga yang disebut?','multiple_choice','[\"Sanggul Jawa\",\"Sanggul Goyang\",\"Siger\",\"Mahkota Raja\"]','Sanggul Goyang',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(175,35,'Alat musik utama yang memberikan harmoni melodi Timur Tengah untuk Tari Jepen adalah?','multiple_choice','[\"Sape\",\"Gambus\",\"Gitar listrik\",\"Suling\"]','Gambus',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(176,36,'Gerakan khas kaki melangkah serentak ke depan dan belakang mengikuti ketukan pukulan rebana pada Tari Jepen melambangkan?','multiple_choice','[\"Keseragaman dan nilai kebersamaan gotong royong\",\"Latihan baris berbaris militer\",\"Kemarahan\",\"Ketakutan kepada musuh\"]','Keseragaman dan nilai kebersamaan gotong royong',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(177,36,'Tari Jepen Eran adalah salah satu variasi Tari Jepen yang sering dipentaskan di?','multiple_choice','[\"Tengah hutan\",\"Pesta rakyat dan penyambutan tamu\",\"Upacara pemakaman\",\"Medan pertempuran\"]','Pesta rakyat dan penyambutan tamu',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(178,36,'Dahulu kala, penari Jepen mayoritas adalah?','multiple_choice','[\"Anak kecil laki-laki\",\"Pria dewasa (karena larangan wanita tampil publik di era ketat)\",\"Hanya wanita tua\",\"Bangsawan keraton murni\"]','Pria dewasa (karena larangan wanita tampil publik di era ketat)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(179,36,'[HOTS - Analisis Keselarasan Koreografi dan Irama] Dalam Tari Jepen Kutai, ketukan kaki melangkah mengikuti pukulan rebana ketipung dengan pola ritme yang sinkopatif (aksen pada ketukan tak terduga). Makna keselarasan antara gerak tubuh yang santun dan ritme dinamis ini adalah...','multiple_choice','[\"Penari mengekspresikan kemarahan yang tertahan di dalam hati\",\"Ekspresi jiwa yang dinamis dan optimis dalam menjalani kehidupan, namun tetap terkendali dalam bingkai etika dan kesantunan budi pekerti Melayu yang luhur\",\"Ketidakmampuan penari mengikuti irama musik pengiring yang terlalu cepat\",\"Tanda bahwa tarian tersebut diperuntukkan bagi ritual ilmu kekebalan tubuh\"]','Ekspresi jiwa yang dinamis dan optimis dalam menjalani kehidupan, namun tetap terkendali dalam bingkai etika dan kesantunan budi pekerti Melayu yang luhur','Filosofi Jepen adalah \"dinamis tapi terkendali\": kaki melangkah tangkas menandakan vitalitas kerja keras, sementara badan merunduk teduh menandakan adab moral.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(180,36,'[HOTS - Analisis Busana Tari Jepen] Penari Tari Jepen mengenakan busana lengan panjang santun yang dipadukan dengan sarung tenun Samarinda/Kutai dan selendang songket. Pilihan kostum ini membuktikan bahwa estetika gerak seni Kutai berpegang pada nilai...','multiple_choice','[\"Pamer kemewahan busana impor dari luar negeri\",\"Menjaga martabat aurat dan kehormatan tubuh penari sesuai kaidah moralitas Islam yang menyatu dengan keanggunan busana istana\",\"Kewajiban mengenakan baju tebal demi menahan cuaca dingin kutub\",\"Peniruan langsung busana tari balet Eropa\"]','Menjaga martabat aurat dan kehormatan tubuh penari sesuai kaidah moralitas Islam yang menyatu dengan keanggunan busana istana','Seni pertunjukan Melayu-Kutai menjunjung tinggi adab: keindahan tarian tidak dieksploitasi melalui keterbukaan fisik, melainkan melalui keluwesan gerak tangan dan ekspresi wajah bersahaja.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(181,37,'Festival atau upacara adat keraton terbesar dari Suku Kutai adalah?','multiple_choice','[\"Iraw Tengkayu\",\"Erau (Erau Adat Pelas Benua)\",\"Cap Go Meh\",\"Lompat Batu\"]','Erau (Erau Adat Pelas Benua)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(182,37,'Kata \"Erau\" berasal dari bahasa Kutai \"Eroh\" yang artinya?','multiple_choice','[\"Menangis\",\"Ramai, riuh rendah, dan suasana gembira\",\"Tidur\",\"Makan\"]','Ramai, riuh rendah, dan suasana gembira',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(183,37,'Pada zaman Kesultanan Kutai kuno, upacara Erau pertama kali digelar dalam rangka?','multiple_choice','[\"Peringatan hari ulang tahun provinsi\",\"Tijak tanah (turun tanah) dan pemberian nama putra mahkota\",\"Keberangkatan pasukan perang\",\"Pembangunan jembatan\"]','Tijak tanah (turun tanah) dan pemberian nama putra mahkota',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(184,37,'Hewan mitologi dari kain dan rangka bambu berwujud ular naga yang diarak dan ditenggelamkan ke Sungai Mahakam pada akhir Erau disebut?','multiple_choice','[\"Naga Basimbur \\/ Mengulur Naga\",\"Barongsai Naga\",\"Naga Bonar\",\"Ular Kobra Kuning\"]','Naga Basimbur / Mengulur Naga',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(185,37,'Acara puncak memercikkan/menyiram air kepada warga setelah naga ditenggelamkan untuk membuang kesialan (tolak bala) disebut?','multiple_choice','[\"Perang ketupat\",\"Belimbur\",\"Mandi uap\",\"Siram rohani\"]','Belimbur',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(186,38,'Pihak yang memimpin jalannya upacara ritual-ritual sakral dalam perayaan Erau (selain Sultan) adalah tetua adat yang disebut?','multiple_choice','[\"Dukun beranak\",\"Belian dan Dewa (Pemimpin ritual)\",\"Juru Kunci gunung\",\"Kades (Kepala Desa)\"]','Belian dan Dewa (Pemimpin ritual)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(187,38,'Tarian sakral mengelilingi tiang Ayu di Keraton Kutai yang ditarikan pada malam-malam pelaksanaan Erau adalah Tari?','multiple_choice','[\"Tari Kecak\",\"Tari Dewa Memanah \\/ Tari Belian\",\"Tari Jepen\",\"Tari Perang\"]','Tari Dewa Memanah / Tari Belian',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(188,38,'Kapan Festival Erau (Tenggarong) di masa kini biasa diselenggarakan sebagai daya tarik pariwisata internasional (TIFAF)?','multiple_choice','[\"Bertepatan hari Pahlawan 10 Nov\",\"Dirangkaikan dengan peringatan hari jadi kota Tenggarong (September\\/Agustus)\",\"Tahun Baru Masehi\",\"Tiap akhir pekan\"]','Dirangkaikan dengan peringatan hari jadi kota Tenggarong (September/Agustus)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(189,38,'[HOTS - Analisis Makna Simbolik Upacara \"Bepelas\"] Pada upacara Bepelas dalam rangkaian Erau, Sultan Kutai menginjakkan kakinya pada gong pusaka sebanyak ketukan ganjil (1 hingga 7 kali) diiringi letusan meriam. Makna filosofis ritual Bepelas ini adalah...','multiple_choice','[\"Menunjukkan kekuatan fisik kaki penguasa yang mampu meremukkan logam\",\"Penguatan kembali ikatan spiritual (energi rohani) dan legitimasi kepemimpinan Sultan dalam mengayomi rakyatnya dari alam semesta hingga bumi tempat berpijak\",\"Hukuman bagi musuh kerajaan yang telah menyerah\",\"Tanda bahwa Sultan akan mengundurkan diri dari tahta kerajaan\"]','Penguatan kembali ikatan spiritual (energi rohani) dan legitimasi kepemimpinan Sultan dalam mengayomi rakyatnya dari alam semesta hingga bumi tempat berpijak','Gong adalah simbol resonansi bumi; sentuhan kaki Sultan pada gong melambangkan pengukuhan mandat kosmis untuk memimpin dengan keadilan dan melindungi segenap rakyat.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(190,38,'[HOTS - Evaluasi Transformasi Festival Adat Erau] Di era modern, Festival Erau bertransformasi menjadi Erau International Folk Art Festival (EIFAF) yang mengundang duta seni dari puluhan negara dunia ke Kalimantan. Dampak positif dari diplomasi kebudayaan ini bagi Kaltara adalah...','multiple_choice','[\"Menghapus seluruh adat istiadat leluhur dan menggantinya dengan seni barat\",\"Memperkenalkan kedaulatan seni budaya Kalimantan ke pentas peradaban global serta membangun rasa bangga generasi muda terhadap identitas budayanya\",\"Mewajibkan seluruh seniman lokal menyanyikan lagu berbahasa Inggris\",\"Mengurangi minat wisatawan mancanegara untuk berkunjung ke Indonesia\"]','Memperkenalkan kedaulatan seni budaya Kalimantan ke pentas peradaban global serta membangun rasa bangga generasi muda terhadap identitas budayanya','Diplomasi budaya internasional membuktikan bahwa tradisi lokal Borneo bernilai universal dan memiliki daya tawar tinggi di kancah peradaban dunia.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(191,39,'Orkes / ansambel musik khas Suku Kutai yang sering membawakan lagu-lagu berbalas pantun disebut musik?','multiple_choice','[\"Gamelan\",\"Tingkilan\",\"Keroncong\",\"Campursari\"]','Tingkilan',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(192,39,'Instrumen petik berlengan panjang khas Timur Tengah yang memegang peranan utama melodi dalam Tingkilan adalah?','multiple_choice','[\"Kecapi\",\"Gambus\",\"Sape\",\"Biola\"]','Gambus',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(193,39,'Kata \"Tingkilan\" berasal dari bahasa Kutai \"Tingkil\" yang bermakna?','multiple_choice','[\"Menyanyi sedih\",\"Saling sindir \\/ berbalas pantun secara bergantian dengan nada\",\"Berlari cepat\",\"Memasak makanan\"]','Saling sindir / berbalas pantun secara bergantian dengan nada',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(194,39,'Lagu (syair) Kutai yang sangat populer dan sering dilantunkan menggunakan iringan Tingkilan adalah lagu berjudul?','multiple_choice','[\"Ampar-ampar Pisang\",\"Buah Bolok\",\"Yamko Rambe\",\"Rasa Sayange\"]','Buah Bolok',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(195,39,'Fungsi sosial orkes Tingkilan pada masa lampau digunakan oleh para pemuda-pemudi Kutai sebagai sarana untuk?','multiple_choice','[\"Ajang mencari jodoh \\/ bertukar kasih (pancaran)\",\"Berlatih perang\",\"Membangun rumah\",\"Menidurkan bayi\"]','Ajang mencari jodoh / bertukar kasih (pancaran)',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(196,40,'Alat perkusi pelengkap untuk menjaga ketukan dalam musik Tingkilan selain Ketipung (Rebana) adalah?','multiple_choice','[\"Drum set\",\"Bedug mesjid\",\"Kendang\",\"Tamborin modern (di masa kini) \\/ Gendang marwas\"]','Tamborin modern (di masa kini) / Gendang marwas',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(197,40,'Isi lirik pantun Tingkilan biasanya dibagi menjadi beberapa bait yang polanya sangat mirip dengan?','multiple_choice','[\"Pantun Melayu\",\"Puisi kontemporer\",\"Karangan bebas prosa\",\"Lirik bahasa Inggris\"]','Pantun Melayu',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(198,40,'Lagu \"Buah Bolok\" yang sering dimainkan dengan iringan Tingkilan bercerita tentang buah asam khas Kalimantan dan mengandung pesan moral agar masyarakat Kutai rajin?','multiple_choice','[\"Berjudi\",\"Bekerja, membangun daerah, dan tidak malas\",\"Berburu binatang langka\",\"Merantau jauh\"]','Bekerja, membangun daerah, dan tidak malas',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(199,40,'[HOTS - Analisis Struktur Pantun \"Betimang\" Kutai] Dalam seni bertutur Kutai, pantun nasehat sering disusun dengan rima bersilang a-b-a-b yang menggunakan kiasan perahu, arus air, dan pohon beringin. Nilai sastra tingkat tinggi dari penggunaan kiasan alam ini adalah...','multiple_choice','[\"Ketiadaan kata-kata modern dalam kamus bahasa Kutai kuno\",\"Menghubungkan hukum etika kemanusiaan dengan hukum alam (makrokosmos) sehingga nasehat kehidupan terdengar abadi dan meresap ke dalam sanubari pendengar\",\"Taktik membingungkan musuh agar tidak memahami isi pembicaraan\",\"Hanya berfungsi mengisi kekosongan bait lagu tingkilan\"]','Menghubungkan hukum etika kemanusiaan dengan hukum alam (makrokosmos) sehingga nasehat kehidupan terdengar abadi dan meresap ke dalam sanubari pendengar','Metafora alam dalam pantun Kutai adalah kearifan epistemologis: menjadikan fenomena alam sebagai cermin moral bagi perilaku manusia.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(200,40,'[HOTS - Studi Kasus Pelestarian Seni Tingkilan di Kalangan Pelajar] Sebuah sekolah di Bulungan mewajibkan ekstrakurikuler musik Tingkilan bagi seluruh siswa kelas VII. Pendekatan pembelajaran apa yang paling memotivasi siswa agar tidak merasa musik tradisional itu kuno?','multiple_choice','[\"Menghukum siswa yang tidak hafal lirik bahasa daerah\",\"Mengkolaborasikan instrumen gambus tingkilan dengan alat musik modern (seperti gitar akustik dan cajon) untuk membawakan lagu daerah beraransemen pop etnik kekinian\",\"Melarang siswa memainkan alat musik modern sama sekali\",\"Memaksa siswa menghafal sejarah silsilah kerajaan selama jam latihan musik\"]','Mengkolaborasikan instrumen gambus tingkilan dengan alat musik modern (seperti gitar akustik dan cajon) untuk membawakan lagu daerah beraransemen pop etnik kekinian','Inovasi kurikulum musik etnik berbasis kolaborasi fusion terbukti meningkatkan \"sense of belonging\" siswa tanpa mengurangi penghargaan terhadap pakem tradisional.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(201,41,'Nasi khas suku Kutai yang dicampur sayur mayur, ikan asin, rempah, dan dimasak secara tradisional (diputar-putar) di atas arang (kuali tanah liat) disebut?','multiple_choice','[\"Nasi Lemak\",\"Nasi Bekepor\",\"Nasi Kuning\",\"Nasi Uduk\"]','Nasi Bekepor',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(202,41,'Lauk utama hidangan ikan gabus bakar bersiram sambal rempah kasar pedas (tomat, bawang merah, cabai) di atasnya dinamakan?','multiple_choice','[\"Gence Ruan\",\"Ikan Pepes\",\"Ikan Bakar Bumbu Rujak\",\"Ikan Peda Goreng\"]','Gence Ruan',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(203,41,'Kata \"Ruan\" dalam \"Gence Ruan\" adalah singkatan nama lokal dari ikan predator sungai Kalimantan yaitu ikan?','multiple_choice','[\"Ikan Koi\",\"Ikan Haruan (Gabus)\",\"Ikan Paus\",\"Ikan Mas\"]','Ikan Haruan (Gabus)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(204,41,'Sayur berkuah santan khas Kutai berbahan sayur pakis/kelakai, umbi, dan disajikan bersama Nasi Bekepor adalah sayur?','multiple_choice','[\"Sayur Lodeh\",\"Sayur Gangan Manok\",\"Sayur Asam\",\"Gangan Keladi (Sayur Asam Keladi Kutai)\"]','Gangan Keladi (Sayur Asam Keladi Kutai)',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(205,41,'Bumbu rahasia yang memberikan wangi menyengat khas daun (mirip daun kemangi) pada masakan daging/ayam Kutai adalah daun?','multiple_choice','[\"Daun Pisang\",\"Daun Ruku-ruku atau Kemangi Kutai\",\"Daun Singkong\",\"Daun Teh\"]','Daun Ruku-ruku atau Kemangi Kutai',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(206,42,'Nasi Bekepor pada masa lampau adalah makanan kaum bangsawan Kutai yang disajikan secara eksklusif menggunakan kendi berukir perak. Ini membuktikan kuliner ini berakar dari?','multiple_choice','[\"Hutan belantara\",\"Masakan dapur Keraton Kesultanan Kutai\",\"Warung pinggir jalan\",\"Makanan laut\"]','Masakan dapur Keraton Kesultanan Kutai',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(207,42,'Kue tradisional (jajanan manis) Suku Kutai bertekstur legit seperti dodol yang dibungkus anyaman daun kelapa (janur) panjang disebut kue?','multiple_choice','[\"Kue Lapis\",\"Jelore \\/ Jajanan Ilat Sapi\",\"Buras\",\"Elat Sapi \\/ Jenderal Mabuk\"]','Elat Sapi / Jenderal Mabuk',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(208,42,'Kata \"Gence\" pada hidangan \"Gence Ruan\" berarti teknik bumbu goreng setengah matang (sambal tumis kasar) yang disiramkan. Teknik bumbu ini menghasilkan rasa dominan?','multiple_choice','[\"Sangat manis seperti sirup\",\"Pedas, manis samar, asin, dan segar asam\",\"Pahit sekali\",\"Hambar \\/ tawar\"]','Pedas, manis samar, asin, dan segar asam',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(209,42,'[HOTS - Analisis Teknik Gastronomi \"Nasi Bekepor\"] Nasi Bekepor dimasak di dalam periuk kendil besi tradisional dengan mencampurkan beras, daun salam, serai, daun kemangi, dan ikan asin yang diaduk berputar saat nasi mendidih. Keistimewaan metode pembakaran kendil ini secara termal dan rasa adalah...','multiple_choice','[\"Menghanguskan seluruh nasi hingga menjadi abu hitam pekat\",\"Menciptakan kerak nasi gurih beraroma asap alami (smoky) yang menginfus minyak rempah dan aroma gurih ikan asin ke setiap butir beras secara merata\",\"Menghilangkan seluruh vitamin dan mineral yang ada di dalam beras\",\"Membuat waktu memasak menjadi sepuluh kali lebih lama dari rice cooker biasa\"]','Menciptakan kerak nasi gurih beraroma asap alami (smoky) yang menginfus minyak rempah dan aroma gurih ikan asin ke setiap butir beras secara merata','Teknik bekepor adalah teknik arang kuno: panas merata dinding kendil besi mengekstrak minyak atsiri daun kemangi-serai dan lemak gurih ikan asin ke inti butiran nasi.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(210,42,'[HOTS - Analisis Bumbu Sambal Gence Ruan] Ikan gabus bakar (haruan) pada kuliner Gence Ruan disiram sambal tumis kasar yang kaya akan bawang merah, cabai tiung, dan perasan air jeruk nipis tanpa menggunakan santan kental. Analisis nutrisi dan kesehatan dari hidangan ini menunjukkan bahwa...','multiple_choice','[\"Kuliner ini berbahaya karena tidak menggunakan pengawet kimia buatan\",\"Kaya akan protein albumin tinggi dari ikan gabus untuk regenerasi sel tubuh yang dipadukan dengan antioksidan allicin bawang merah dan vitamin C segar minim kolesterol jenuh\",\"Hanya cocok dikonsumsi oleh kalangan olahragawan berat\",\"Merupakan makanan berkalori kosong yang tidak memiliki nilai gizi\"]','Kaya akan protein albumin tinggi dari ikan gabus untuk regenerasi sel tubuh yang dipadukan dengan antioksidan allicin bawang merah dan vitamin C segar minim kolesterol jenuh','Ikan haruan terkenal dengan kandungan albumin penyembuh luka; bumbu tumis rempah segar tanpa santan menjadikannya hidangan lezat berstandar medis alami.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(211,43,'Pusat pemerintahan Kesultanan Kutai Kartanegara (Istana) dan arsitektur keratonnya terletak di kota?','multiple_choice','[\"Balikpapan\",\"Tenggarong\",\"Tarakan\",\"Samarinda\"]','Tenggarong',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(212,43,'Bangunan peninggalan Keraton Kutai (Kedaton) saat ini beralih fungsi dan ditetapkan oleh pemerintah sebagai?','multiple_choice','[\"Gedung DPRD\",\"Museum Mulawarman\",\"Pasar Tradisional\",\"Rumah Sakit Daerah\"]','Museum Mulawarman',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(213,43,'Arsitektur bangunan Museum Mulawarman (eks Istana Kutai generasi baru) dibangun kuat memadukan unsur seni ukir Kutai dengan arsitektur corak kolonial?','multiple_choice','[\"Jepang modern\",\"Spanyol \\/ Romawi Eropa dan Belanda (Indis)\",\"Tiongkok\",\"Timur Tengah klasik\"]','Spanyol / Romawi Eropa dan Belanda (Indis)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(214,43,'Tiang bendera keraton bersejarah yang berdiri di depan Istana Kutai dan terbuat dari kayu ulin raksasa dikenal dengan sebutan?','multiple_choice','[\"Tiang Monas\",\"Tiang Ayu \\/ Tiang Bendera Sumbu Kurung\",\"Tiang Pancang\",\"Tiang Listrik\"]','Tiang Ayu / Tiang Bendera Sumbu Kurung',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(215,43,'Warna dominan yang menjadi simbol kebesaran Kerajaan Kutai dan dihiaskan pada panji-panji keraton adalah warna?','multiple_choice','[\"Biru langit\",\"Kuning emas (Kuning keemasan)\",\"Hitam pekat\",\"Ungu gelap\"]','Kuning emas (Kuning keemasan)',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(216,44,'Ornamen naga bersayap melingkar yang berada di gerbang istana maupun di singgasana Raja melambangkan penguasa alam mitologi Hindu Kutai yaitu legenda Lembuswana. Bentuk fisik hewan mitologi Lembuswana menggabungkan unsur?','multiple_choice','[\"Gajah, burung garuda, naga, dan harimau\",\"Singa, ikan, dan burung pipit\",\"Kuda, anjing, dan kera\",\"Kerbau, buaya, dan gagak\"]','Gajah, burung garuda, naga, dan harimau',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(217,44,'Singgasana raja Kesultanan Kutai yang tersimpan di dalam museum terbuat dari?','multiple_choice','[\"Rotan anyam\",\"Batu granit\",\"Kayu berukir lapisan emas\",\"Besi tua\"]','Kayu berukir lapisan emas',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(218,44,'Secara tata ruang kosmologis, bagian terdepan (alun-alun halaman luas) Istana Kutai berhadapan langsung dengan?','multiple_choice','[\"Gunung berapi\",\"Sungai Mahakam\",\"Hutan pinus\",\"Gurun pasir\"]','Sungai Mahakam',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(219,44,'[HOTS - Analisis Gaya Arsitektur Ekletik Istana] Bangunan Keraton Kutai diresmikan tahun 1936 dengan memadukan gaya arsitektur Art Deco / Neoklasik Eropa pada bagian dinding dan pilar beton dengan ornamen ukiran kayu khas Melayu-Borneo di bagian interior. Mengapa Sultan Kutai saat itu memilih perpaduan arsitektur eklektik ini?','multiple_choice','[\"Karena arsitek lokal melarikan diri ke luar pulau\",\"Menunjukkan sikap keterbukaan modernitas dan diplomasi internasional yang setara dengan bangsa barat, namun tetap berpijak teguh pada akar identitas kultural Kalimantan\",\"Hanya sekadar meniru gambar bangunan dari majalah bekas\",\"Sebagai tanda penyerahan kedaulatan kerajaan secara mutlak kepada penjajah\"]','Menunjukkan sikap keterbukaan modernitas dan diplomasi internasional yang setara dengan bangsa barat, namun tetap berpijak teguh pada akar identitas kultural Kalimantan','Arsitektur keraton adalah bahasa diplomasi visual: membuktikan kepada dunia kolonial bahwa Kesultanan Kutai adalah entitas berdaulat yang maju dan berbudaya tinggi.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(220,44,'[HOTS - Analisis Perlindungan Benda Pusaka Keraton] Di dalam museum istana tersimpan benda pusaka seperti Mahkota Sultan dari emas bermata permata, Pedang Kemala, dan Kalung Uncal peninggalan era Hindu-Jawa. Keberadaan Kalung Uncal yang berhiaskan relief kisah Ramayana ini membuktikan bahwa...','multiple_choice','[\"Kerajaan Kutai tidak memiliki hubungan perniagaan dengan pulau lain di Nusantara\",\"Telah terjalin konektivitas budaya dan diplomasi upeti\\/perkawinan politik yang sangat erat antara Kerajaan Kutai di Kalimantan dengan Kerajaan Majapahit di Jawa pada abad pertengahan\",\"Benda pusaka tersebut baru dibuat pada awal abad ke-21 untuk kepentingan pariwisata\",\"Masyarakat Kutai kuno menolak seluruh kebudayaan dari luar pulau\"]','Telah terjalin konektivitas budaya dan diplomasi upeti/perkawinan politik yang sangat erat antara Kerajaan Kutai di Kalimantan dengan Kerajaan Majapahit di Jawa pada abad pertengahan','Kalung Uncal (hanya ada dua di dunia: di India dan Kutai) adalah bukti arkeologis jejaring diplomasi maritim adiluhung Nusantara masa lampau.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(221,45,'Tenun Ulap Doyo adalah mahakarya seni tekstil tradisional kalimantan yang diciptakan oleh sub-suku dari wilayah pedalaman Kutai, yaitu?','multiple_choice','[\"Dayak Punan\",\"Dayak Benuaq\",\"Suku Bugis\",\"Dayak Iban\"]','Dayak Benuaq',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(222,45,'Bahan dasar pintalan benang Ulap Doyo bukan berasal dari kapas atau sutra ulat, melainkan serat daun dari tanaman semak liar bernama?','multiple_choice','[\"Daun teh\",\"Daun tanaman Doyo (Curculigo latifolia)\",\"Daun pandan\",\"Daun teratai\"]','Daun tanaman Doyo (Curculigo latifolia)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(223,45,'Kata \"Ulap\" dalam bahasa Benuaq memiliki arti?','multiple_choice','[\"Ular phyton\",\"Kain penutup tubuh \\/ kain sarung\",\"Pewarna kain\",\"Mesin tenun\"]','Kain penutup tubuh / kain sarung',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(224,45,'Alat tenun tradisional yang digunakan wanita Benuaq untuk membuat Ulap Doyo diselipkan di belakang punggung pinggang penenunnya, disebut jenis alat tenun?','multiple_choice','[\"Alat Tenun Mesin (ATM)\",\"Gedokan \\/ Tenun Ikat Pinggang (Backstrap Loom)\",\"Batik cap\",\"Rotasi engkol otomatis\"]','Gedokan / Tenun Ikat Pinggang (Backstrap Loom)',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(225,45,'Pewarna tradisional merah pada tenun Ulap Doyo sering kali didapat dari getah atau serutan kulit batang pohon?','multiple_choice','[\"Pohon Jati\",\"Pohon Secang \\/ Pohon Gula (Tegeran)\",\"Pohon Beringin\",\"Pohon Pinus\"]','Pohon Secang / Pohon Gula (Tegeran)',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(226,46,'Motif Ulap Doyo bagi pria bangsawan / kepala adat (Mantiq) biasanya diwajibkan bermotif corak margasatwa gagah, seperti motif?','multiple_choice','[\"Kucing dan tikus\",\"Naga (Aso) dan Harimau\",\"Ikan teri\",\"Bunga melati\"]','Naga (Aso) dan Harimau',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(227,46,'Motif floral dan tumbuhan menjalar pada Ulap Doyo secara tradisi biasanya diperuntukkan untuk pakaian wanita bangsawan karena melambangkan?','multiple_choice','[\"Kesedihan\",\"Kelembutan budi, pertumbuhan, dan kesuburan\",\"Semangat perangkap musuh\",\"Kegelapan\"]','Kelembutan budi, pertumbuhan, dan kesuburan',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(228,46,'Proses paling sulit dalam pembuatan benang Doyo adalah saat mengubah daun panjang menjadi helaian serat tipis. Daun doyo tidak dipotong dengan gunting, melainkan dikikis dengan hati-hati menggunakan alat ukir dari?','multiple_choice','[\"Bilah bambu pelat tipis\",\"Besi panas gergaji\",\"Kapak tebang\",\"Korek api\"]','Bilah bambu pelat tipis',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(229,46,'[HOTS - Analisis Keberlanjutan Bahan Baku Serat Alam] Tenun Ulap Doyo dipintal dari serat daun tanaman Doyo (Curculigo latifolia) yang tumbuh liar tanpa pestisida di lantai hutan pedalaman Kalimantan. Mengapa kain tenun berbasis serat daun liar ini dipandang sebagai masa depan industri fesyen berkelanjutan (sustainable eco-fashion)?','multiple_choice','[\"Karena tanaman doyo hanya bisa tumbuh di laboratorium kimia buatan\",\"Serat doyo bersifat 100% organik, kuat, memiliki kilau alami seperti sutra, dapat terurai alami (biodegradable), dan konservasinya menjaga kelestarian tegakan pohon hutan primer\",\"Karena kain doyo tidak membutuhkan keahlian menenun manusia\",\"Karena harga kain doyo dapat dibuat lebih murah daripada kain sintetis plastik\"]','Serat doyo bersifat 100% organik, kuat, memiliki kilau alami seperti sutra, dapat terurai alami (biodegradable), dan konservasinya menjaga kelestarian tegakan pohon hutan primer','Ulap Doyo adalah mahakarya fesyen ekologis: tanaman Doyo membutuhkan naungan kanopi hutan lebat untuk bertahan hidup; melestarikan Doyo berarti menjaga hutan dari deforestasi.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(230,46,'[HOTS - Analisis Motif Geometris dan Nilai Sakral Tenun] Motif tenun Ulap Doyo memiliki aturan bahwa motif tertentu (seperti motif naga/lemba) pada masa lampau hanya boleh dipakai oleh kaum bangsawan mantik. Perubahan fungsi tenun ini di era demokrasi modern sebaiknya dimaknai sebagai...','multiple_choice','[\"Penghancuran nilai sejarah adat leluhur\",\"Demokratisasi apresiasi budaya di mana setiap warga negara dapat mengenakan dan melestarikan mahakarya warisan leluhur dengan tetap menghormati makna filosofisnya\",\"Kewajiban membakar kain tenun yang bermotif bangsawan\",\"Penjualan bebas tanpa perlu mencantumkan asal-usul kearifan lokalnya\"]','Demokratisasi apresiasi budaya di mana setiap warga negara dapat mengenakan dan melestarikan mahakarya warisan leluhur dengan tetap menghormati makna filosofisnya','Transformasi dari simbol kasta feodal menjadi identitas kebanggaan bersama adalah proses evolusi budaya yang wajar demi pelestarian di era kesetaraan hak warga negara.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(231,47,'Suku Tidung merupakan penduduk asli yang mayoritas mendiami wilayah pesisir utara dan pulau-pulau di provinsi?','multiple_choice','[\"Kalimantan Selatan\",\"Kalimantan Timur\",\"Kalimantan Utara (khususnya Tarakan & Nunukan)\",\"Kalimantan Barat\"]','Kalimantan Utara (khususnya Tarakan & Nunukan)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(232,47,'Nama \"Tidung\" diperkirakan berasal dari kata bahasa lokal \"Tideng\" yang artinya?','multiple_choice','[\"Gunung atau bukit\",\"Sungai panjang\",\"Laut dalam\",\"Hutan pinus\"]','Gunung atau bukit',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(233,47,'Secara asal usul rumpun, Suku Tidung (Tengara) masih memiliki kedekatan kekerabatan darah (serumpun) dengan suku?','multiple_choice','[\"Suku Bugis Makassar\",\"Suku Dayak (Rumpun Murut \\/ Dayak Utara)\",\"Suku Jawa Mataram\",\"Suku Madura\"]','Suku Dayak (Rumpun Murut / Dayak Utara)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(234,47,'Agama mayoritas yang dianut oleh masyarakat Suku Tidung saat ini dan membentuk kebudayaannya secara kuat (menjadi suku pesisir) adalah?','multiple_choice','[\"Kristen Katolik\",\"Islam\",\"Hindu Kaharingan\",\"Konghucu\"]','Islam',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(235,47,'Pusat kebudayaan maritim dan pusat kerajaan historis Suku Tidung dahulu berada di wilayah kerajaan/kesultanan?','multiple_choice','[\"Kesultanan Ternate\",\"Kerajaan Kutai\",\"Kerajaan Tidung \\/ Dinasti Tengara (Tarakan)\",\"Kerajaan Banten\"]','Kerajaan Tidung / Dinasti Tengara (Tarakan)',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(236,48,'Karena letaknya di wilayah pesisir kepulauan, mata pencaharian tradisional mayoritas masyarakat Suku Tidung adalah sebagai?','multiple_choice','[\"Petani apel\",\"Nelayan (pencari ikan laut) dan pedagang pesisir\",\"Penambang emas\",\"Penebang pohon jati\"]','Nelayan (pencari ikan laut) dan pedagang pesisir',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(237,48,'Suku Tidung sering disebut sebagai suku \"Pesisir\" bersama dengan suku tetangganya yang erat sejarahnya dengan Kesultanan?','multiple_choice','[\"Suku Bulungan\",\"Suku Asmat\",\"Suku Mentawai\",\"Suku Sasak\"]','Suku Bulungan',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(238,48,'Sistem monarki/pemerintahan suku Tidung masa lampau dipimpin oleh penguasa yang bergelar?','multiple_choice','[\"Gubernur\",\"Raja \\/ Sultan (Gelar Datuk atau Amiril)\",\"Presiden\",\"Bupati\"]','Raja / Sultan (Gelar Datuk atau Amiril)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(239,48,'[HOTS - Analisis Geopolitik Kerajaan Pesisir Tarakan] Letak geografis Pulau Tarakan dan muara sungai Sesayap yang strategis di jalur pelayaran segitiga Sulawesi-Borneo-Sulu menjadikan Kerajaan Tidung sebagai bandar perdagangan maritim penting. Dampak geopolitik dari posisi strategis ini terhadap kebudayaan Suku Tidung adalah...','multiple_choice','[\"Masyarakat Tidung menjadi suku yang sangat terisolasi dari peradaban dunia\",\"Terbentuknya karakter budaya maritim yang terbuka, multilingual (menguasai bahasa Melayu, Tidung, dan Sulu), serta adaptif terhadap interaksi antarbangsa bahari\",\"Pemusnahan seluruh armada perahu tradisional nelayan Tidung\",\"Peralihan total mata pencaharian warga dari nelayan menjadi peternak unta\"]','Terbentuknya karakter budaya maritim yang terbuka, multilingual (menguasai bahasa Melayu, Tidung, dan Sulu), serta adaptif terhadap interaksi antarbangsa bahari','Pesisir Tarakan adalah simpul perairan internasional: keterbukaan maritim membentuk kosmopolitanisme budaya Tidung yang toleran dan piawai bernavigasi samudera.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(240,48,'[HOTS - Analisis Asal-Usul Etnonim \"Tidung\"] Secara etimologi bahasa daerah, kata \"Tidung\" berakar dari kata \"Tideng\" yang bermakna bukit atau gunung kecil di pulau pesisir. Analisis antropologis mengapa suku yang mendiami pantai dan laut ini menyandang nama \"orang bukit\" adalah...','multiple_choice','[\"Karena nenek moyang suku Tidung tidak pernah melihat laut lepas\",\"Jejak historis migrasi nenek moyang suku Tidung yang awalnya berasal dari perbukitan hulu pedalaman sebelum bermigrasi ke muara sungai dan menguasai pesisir laut Kaltara\",\"Hanya kesalahan pencatatan oleh pedagang bangsa Belanda\",\"Sebagai kamuflase militer agar bajak laut tidak menyerang pemukiman pesisir\"]','Jejak historis migrasi nenek moyang suku Tidung yang awalnya berasal dari perbukitan hulu pedalaman sebelum bermigrasi ke muara sungai dan menguasai pesisir laut Kaltara','Etnonim \"Tideng\" adalah rekaman fosil sejarah migrasi rumpun Murutic: bergerak turun menyusuri aliran sungai Sesayap dan Malinau hingga bertransformasi menjadi pelaut handal pesisir Tarakan.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(241,49,'Upacara adat (festival budaya) turun-temurun terbesar milik masyarakat suku Tidung di Kota Tarakan dinamakan?','multiple_choice','[\"Erau Kutai\",\"Iraw Tengkayu\",\"Lompat Batu\",\"Cap Go Meh\"]','Iraw Tengkayu',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(242,49,'Kata \"Iraw\" dalam bahasa lokal Tidung/Dayak bermakna?','multiple_choice','[\"Kesedihan\",\"Pesta rakyat, perayaan, atau upacara gembira\",\"Perang suku\",\"Mencari ikan di laut\"]','Pesta rakyat, perayaan, atau upacara gembira',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(243,49,'Tujuan utama (filosofi) diselenggarakannya Iraw Tengkayu oleh masyarakat pesisir Tidung adalah sebagai ritual?','multiple_choice','[\"Syukuran \\/ Sedekah laut atas rezeki tangkapan nelayan dan tolak bala\",\"Menutup akses laut agar tidak ada kapal masuk\",\"Hanya untuk lomba lari\",\"Pamer kekayaan harta\"]','Syukuran / Sedekah laut atas rezeki tangkapan nelayan dan tolak bala',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(244,49,'Objek paling penting / ikonik yang diarak warga keliling kota sebelum dilarungkan ke tengah laut pada saat Iraw Tengkayu adalah?','multiple_choice','[\"Patung Naga Emas\",\"Padaw Tuju Dulung (Perahu Tujuh Haluan)\",\"Kereta Kencana Kuda\",\"Meriam peninggalan Belanda\"]','Padaw Tuju Dulung (Perahu Tujuh Haluan)',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(245,49,'Biasanya acara puncak Iraw Tengkayu (pelarungan perahu adat) dilaksanakan setiap dua tahun sekali di lokasi?','multiple_choice','[\"Puncak Gunung Krayan\",\"Pantai Amal Kota Tarakan (Tepi Laut Mamburungan)\",\"Sungai Mahakam\",\"Danau Toba\"]','Pantai Amal Kota Tarakan (Tepi Laut Mamburungan)',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(246,50,'Angka \"Tuju\" (Tujuh) pada perahu Padaw Tuju Dulung bermakna sangat filosofis dan magis bagi suku Tidung karena angka 7 melambangkan?','multiple_choice','[\"Tujuh hari kemarau\",\"Jumlah hari dalam sepekan kehidupan manusia dan keturunan lurus dewa-dewa Tidung\",\"Tujuh warna pelangi\",\"Tujuh pahlawan super\"]','Jumlah hari dalam sepekan kehidupan manusia dan keturunan lurus dewa-dewa Tidung',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(247,50,'Perahu Padaw Tuju Dulung dihias dengan perpaduan 3 warna sakral adat Tidung, yaitu?','multiple_choice','[\"Kuning, Hijau, dan Merah\",\"Hitam, Putih, dan Abu\",\"Pink, Biru, dan Ungu\",\"Cokelat kayu polos\"]','Kuning, Hijau, dan Merah',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(248,50,'Apa sajakah isi bawaan persembahan (sesaji) yang dimuat ke dalam lambung kapal Padaw Tuju Dulung untuk dilarung ke laut?','multiple_choice','[\"Senjata tajam dan peluru\",\"Makanan tradisional (Nasi rasul, kue-kue, hasil bumi\\/pertanian)\",\"Emas batangan murni\",\"Batu kali besar\"]','Makanan tradisional (Nasi rasul, kue-kue, hasil bumi/pertanian)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(249,50,'[HOTS - Analisis Nilai Ketauhidan dalam Tradisi Sedekah Laut] Tradisi melarung Padaw Tuju Dulung pada Festival Iraw Tengkayu saat ini selalu diawali dengan pembacaan doa selawat dan ayat suci Al-Qur\'an oleh pemangku adat. Transformasi nilai teologis dari ritual pra-Islam menuju peradaban Islam ini membuktikan bahwa...','multiple_choice','[\"Masyarakat Tidung menolak mentah-mentah seluruh ajaran agama baru\",\"Ritual tersebut telah dimurnikan dari pemujaan dewa laut mistis menjadi ungkapan rasa syukur (tasyakur bi al-ni\'mah) yang ditujukan semata kepada Allah SWT atas rezeki lautan\",\"Acara festival hanya sekadar sandiwara tanpa keyakinan spiritual apa pun\",\"Hukum adat Tidung melarang doa dibacakan dalam bahasa Arab\"]','Ritual tersebut telah dimurnikan dari pemujaan dewa laut mistis menjadi ungkapan rasa syukur (tasyakur bi al-ni\'mah) yang ditujukan semata kepada Allah SWT atas rezeki lautan','Akulturasi Islam pada Iraw Tengkayu menata ulang niat (tauhid): laut adalah ciptaan Tuhan yang harus disyukuri hasil ikannya, bukan dipuja sebagai berhala penguasa semesta.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(250,50,'[HOTS - Analisis Makna Tri-Warna Haluan Perahu Padaw] Perahu Padaw Tuju Dulung dihiasi tiga warna dominan kebesaran adat: Kuning, Merah, dan Hijau. Berdasarkan kosmologi kepemimpinan Suku Tidung, warna Kuning pada lambang adat tersebut melambangkan...','multiple_choice','[\"Tanda bahaya akan datangnya badai ombak besar di laut Tarakan\",\"Keagungan tahta kedaulatan, keluhuran budi para pemimpin adat, serta kemuliaan derajat moral yang harus dijunjung tinggi oleh masyarakat\",\"Kemiskinan warga pesisir yang mengharapkan bantuan beras\",\"Tanda perkabungan atas hilangnya perahu nelayan di samudra\"]','Keagungan tahta kedaulatan, keluhuran budi para pemimpin adat, serta kemuliaan derajat moral yang harus dijunjung tinggi oleh masyarakat','Kuning adalah warna sakral raja/pemimpin berdaulat; merah melambangkan keberanian pelaut, dan hijau melambangkan kesuburan serta ketakwaan pada ajaran agama.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(251,51,'Seni tari yang paling dominan di kalangan muda-mudi Suku Tidung Tarakan pada perayaan besar / penyambutan tamu adalah Tari?','multiple_choice','[\"Tari Kecak Bali\",\"Tari Jepen (Zapin) Pesisir Tidung\",\"Tari Kancet Papatai\",\"Tari Hudoq\"]','Tari Jepen (Zapin) Pesisir Tidung',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(252,51,'Tari Jepen pesisir merupakan bukti nyata (akulturasi) pengaruh kuat masuknya agama dan kebudayaan dari daerah?','multiple_choice','[\"Amerika Latin\",\"Islam Arab-Melayu\",\"Jepang dan Korea\",\"Pedalaman hutan rimba\"]','Islam Arab-Melayu',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(253,51,'Gerakan kaki pada Jepen Tidung terkenal dengan tempo gerak yang?','multiple_choice','[\"Lincah, patah-patah ringan selang-seling seirama rentak pukulan gendang\",\"Terdiam tanpa gerak sama sekali\",\"Berguling-guling di lantai keras\",\"Melompat sangat tinggi melebihi kepala\"]','Lincah, patah-patah ringan selang-seling seirama rentak pukulan gendang',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(254,51,'Kesenian musik pengiring yang digunakan mirip dengan Jepen daerah lain, yaitu musik rebana dan petikan dawai arab yang disebut alat musik?','multiple_choice','[\"Gitar Spanyol\",\"Gambus\",\"Harpa Eropa\",\"Piano klasik\"]','Gambus',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(255,51,'Penari wanita Tidung mengenakan pakaian sopan dan tertutup lengan panjang berbahan kain sutra polos/mengkilap warna kuning mencolok, pakaian ini dipengaruhi oleh nilai kesopanan dari agama?','multiple_choice','[\"Islam\",\"Hindu\",\"Buddha\",\"Sikh\"]','Islam',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(256,52,'Gerakan tangan menyilang di dada, menunduk anggun, dan senyum kecil (tidak berlebihan) dalam Jepen Tidung mengandung filosofi tentang?','multiple_choice','[\"Rasa angkuh dan sombong keluarga raja\",\"Adab (budi pekerti), sopan santun, kerendahan hati wanita maritim\",\"Menantang musuh untuk berkelahi fisik\",\"Rasa sedih mendalam karena menangisi laut\"]','Adab (budi pekerti), sopan santun, kerendahan hati wanita maritim',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(257,52,'Selain Jepen, pada festival Iraw Tengkayu, para pemuda (laki-laki) Tidung juga mementaskan sebuah tarian massal (puluhan orang) untuk menyambut Padaw Tuju Dulung yang disebut tari?','multiple_choice','[\"Tari Kuda Lumping\",\"Tari Kedandiu\",\"Tari Tortor\",\"Tari Piring\"]','Tari Kedandiu',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(258,52,'Alat perkusi pengetuk irama tempo (beat) khas Jepen pesisir yang terbuat dari kayu dilapis kulit rusa/kambing dipukul jari berbunyi \"tak-dung\" adalah?','multiple_choice','[\"Ketipung \\/ Marawis (Rebana Pesisir)\",\"Drum set listrik\",\"Gong raksasa dari tembaga Cina\",\"Bedug mesjid berukuran sangat besar\"]','Ketipung / Marawis (Rebana Pesisir)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(259,52,'[HOTS - Komparasi Tari Zapin/Jepen: Tidung vs Kutai] Meskipun sama-sama berakar dari pengaruh tarian Melayu-Arab, Tari Jepen Tidung memiliki tempo ketukan kaki yang relatif lebih lincah dan enerjik dibandingkan Tari Jepen Kutai yang bertempo lebih lambat mengalun. Analisis sosiokultural terhadap perbedaan tempo gerak ini adalah...','multiple_choice','[\"Penari Tidung tidak memahami aturan gerak tari Melayu yang baku\",\"Karakter penari Tidung dipengaruhi oleh dinamika ombak laut pesisir yang dinamis dan ketangkasan fisik nelayan, berbeda dengan Jepen Kutai yang lahir di lingkungan keraton sungai yang tenang\",\"Alat musik pengiring Jepen Tidung dimainkan menggunakan alat musik elektronik modern\",\"Tari Jepen Kutai dilarang diiringi oleh alat musik perkusi gendang\"]','Karakter penari Tidung dipengaruhi oleh dinamika ombak laut pesisir yang dinamis dan ketangkasan fisik nelayan, berbeda dengan Jepen Kutai yang lahir di lingkungan keraton sungai yang tenang','Geografi membentuk estetika gerak: masyarakat bahari Tidung yang terbiasa menerjang ombak melahirkan tarian lincah dan tangkas, sementara istana Kutai melahirkan keanggunan lambat bersahaja.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(260,52,'[HOTS - Analisis Fungsi Komunikasi Sosial Tari Pergaulan] Dalam perayaan pernikahan adat Tidung, Tari Jepen massal sering kali ditarikan bersama oleh tua dan muda di halaman rumah. Nilai kohesi sosial apa yang diperkuat melalui partisipasi tari komunal ini?','multiple_choice','[\"Menentukan pemenang penari terbaik untuk mendapatkan hadiah uang tunai\",\"Mencairkan ketegangan sosial, mempererat rasa persaudaraan warga sekampung, dan meniadakan sekat status ekonomi dalam kegembiraan bersama\",\"Memaksa warga yang hadir untuk memberikan sumbangan uang yang lebih banyak\",\"Menunjukkan kehebatan fisik pemuda dalam bertarung di hadapan pengantin\"]','Mencairkan ketegangan sosial, mempererat rasa persaudaraan warga sekampung, dan meniadakan sekat status ekonomi dalam kegembiraan bersama','Tari pergaulan rakyat adalah katarsis komunal: saat irama gambus berbunyi dan langkah kaki bersatu, perbedaan kelas sosial melebur dalam senyum kebersamaan warga.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(261,53,'Bangunan rumah adat resmi (mahakarya panggung) peninggalan dari sejarah kebesaran Suku Tidung dinamakan rumah adat?','multiple_choice','[\"Rumah Betang\",\"Rumah Baloy (Baloy Adat Tidung)\",\"Rumah Gadang\",\"Rumah Honai\"]','Rumah Baloy (Baloy Adat Tidung)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(262,53,'Seperti arsitektur tradisional Borneo pada umumnya, Baloy dirancang menghadap ke arah sumber kehidupan yaitu?','multiple_choice','[\"Menghadap ke Selatan (Kutub)\",\"Membelakangi jalan raya\",\"Menghadap (Berorientasi) ke perairan \\/ muara sungai (Utara\\/Timur)\",\"Menghadap ke puncak gunung api\"]','Menghadap (Berorientasi) ke perairan / muara sungai (Utara/Timur)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(263,53,'Rumah Baloy didirikan memanjang sebagai rumah panggung, ditopang tiang-tiang bulat besar yang dibuat utuh dari kayu yang terkenal anti lapuk, yaitu?','multiple_choice','[\"Kayu Sengon merah\",\"Kayu Ulin (Kayu Besi Borneo)\",\"Kayu Jati belanda\",\"Bambu wulung tipis\"]','Kayu Ulin (Kayu Besi Borneo)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(264,53,'Bentuk ujung atap (bubungan) rumah Baloy memiliki ukiran khas yang mencuat berornamen pucuk rebung atau naga laut, atap utama ini disebut atap bentuk?','multiple_choice','[\"Atap Kubah\",\"Atap Tinggi \\/ Limas ukiran (Beratap Tumpang)\",\"Atap Genteng beton\",\"Atap Rata asbes\"]','Atap Tinggi / Limas ukiran (Beratap Tumpang)',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(265,53,'Rumah Baloy kuno aslinya tidak dibangun menggunakan paku besi sama sekali, melainkan menggunakan sistem konstruksi?','multiple_choice','[\"Lem super korea\",\"Sistem pasak kayu (paku kayu \\/ bambu) saling kunci\",\"Dililit kawat baja\",\"Diikat tali tambang plastik\"]','Sistem pasak kayu (paku kayu / bambu) saling kunci',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(266,54,'Fungsi asli ruangan utama dalam Rumah Baloy (ruang tengah) bagi masyarakat adat Tidung pada zaman kerajaan adalah sebagai ruang untuk?','multiple_choice','[\"Tempat tidur anak kecil semata\",\"Kandang hewan ternak peliharaan\",\"Ruang Balai Pertemuan (Bicara Adat), musyawarah peradilan, penyelesaian masalah \\/ sengketa warga\",\"Gudang senjata api\"]','Ruang Balai Pertemuan (Bicara Adat), musyawarah peradilan, penyelesaian masalah / sengketa warga',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(267,54,'Sebuah miniatur pusat pelestarian replika \"Baloy Mayo\" (Rumah Baloy Besar) Tidung telah dibangun megah oleh pemerintah kota dan menjadi cagar wisata di daerah?','multiple_choice','[\"Kota Samarinda\",\"Kota Tarakan (Kawasan Amal \\/ Juata)\",\"Kota Pontianak\",\"Kota Palangkaraya\"]','Kota Tarakan (Kawasan Amal / Juata)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(268,54,'Ukiran-ukiran ornamen kuning-merah pada dinding kayu dan ventilasi rumah Baloy Tidung paling banyak bermotifkan unsur flora pesisir yakni daun?','multiple_choice','[\"Daun teh\",\"Daun Pakis (Sulur pakis) atau Kaligrafi sulur-suluran\",\"Daun Jati kering\",\"Bunga Mawar besar\"]','Daun Pakis (Sulur pakis) atau Kaligrafi sulur-suluran',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(269,54,'[HOTS - Analisis Filosofis Rumah Baloy Mayo sebagai Simbol Provinsi] Pemerintah menetapkan Rumah Baloy Mayo sebagai representasi resmi Rumah Adat Provinsi Kalimantan Utara. Alasan filosofis dan arsitektural yang paling mendasar di balik penetapan ini adalah...','multiple_choice','[\"Karena Rumah Baloy adalah bangunan termurah yang dapat didirikan oleh pemerintah\",\"Rumah Baloy mengintegrasikan kecerdasan adaptasi maritim-sungai Kaltara serta melambangkan falsafah \\\"Benuanta Bersatu dalam Keberagaman\\\" di mana empat suku utama hidup harmonis di tanah Kaltara\",\"Karena suku lain di Kalimantan Utara tidak memiliki rumah adat tradisional\",\"Merupakan perintah dari pemerintah kolonial masa lampau yang tidak dapat diubah\"]','Rumah Baloy mengintegrasikan kecerdasan adaptasi maritim-sungai Kaltara serta melambangkan falsafah \"Benuanta Bersatu dalam Keberagaman\" di mana empat suku utama hidup harmonis di tanah Kaltara','Baloy Mayo di Tanjung Selor dibangun sebagai rumah persatuan: arsitekturnya menyerap estetika lokal Kaltara sebagai simbol payung kebersamaan seluruh etnis di provinsi ke-34 ini.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(270,54,'[HOTS - Analisis Rekayasa Lingkungan Rumah Panggung Pesisir] Kolong Rumah Baloy panggung sengaja dirancang terbuka tanpa dinding dan memiliki celah lantai kayu yang presisi. Fungsi aerodinamika dan mitigasi bencana dari rekayasa arsitektur ini adalah...','multiple_choice','[\"Memudahkan sampah dapur dibuang langsung ke bawah tanah\",\"Mengurangi resistensi hantaman angin badai laut dan hempasan gelombang pasang, sekaligus mengalirkan ventilasi silang udara sejuk ke seluruh ruangan rumah\",\"Sebagai kandang ternak sapi perah berskala besar\",\"Agar lantai rumah cepat lapuk dan harus dibangun kembali setiap tahun\"]','Mengurangi resistensi hantaman angin badai laut dan hempasan gelombang pasang, sekaligus mengalirkan ventilasi silang udara sejuk ke seluruh ruangan rumah','Celah lantai dan kolong tinggi adalah aerodinamika vernakular: angin laut tropis bertekanan tinggi dapat menerobos leluasa tanpa meruntuhkan dinding utama rumah.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(271,55,'Sebagai masyarakat yang berakar di daerah pesisir pantai dan pulau kecil (Tarakan/Nunukan), kuliner Suku Tidung selalu didominasi oleh olahan bahan dasar?','multiple_choice','[\"Ayam buras hutan\",\"Seafood \\/ Hasil laut tangkapan (Kerang, Ikan, Udang)\",\"Daging sapi\",\"Sayuran pakis hutan kering\"]','Seafood / Hasil laut tangkapan (Kerang, Ikan, Udang)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(272,55,'Jenis kerang khas laut Tarakan (endemik di pesisir berlumpur pantai Amal) yang cangkangnya tebal, isinya gemuk, dan paling terkenal direbus bersama sambal cocol adalah kerang?','multiple_choice','[\"Kerang Darah \\/ Kerang Dara\",\"Kerang Kapah\",\"Kerang Hijau \\/ Kupang\",\"Tiram (Oyster)\"]','Kerang Kapah',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(273,55,'Sajian khas sate Tidung yang terbuat dari daging ikan (biasanya ikan bandeng) yang durinya dicabut utuh bersih, dagingnya dihaluskan dengan kelapa sangrai dan rempah, lalu dimasukkan lagi ke kulit ikannya kemudian dibakar di atas jepitan bambu disebut?','multiple_choice','[\"Sate Lilit Ayam\",\"Sate Ikan Bandeng (Bandeng Tanpa Duri \\/ Sate Pari)\",\"Otak-otak Ikan Tenggiri\",\"Sate Kerang bumbu kacang\"]','Sate Ikan Bandeng (Bandeng Tanpa Duri / Sate Pari)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(274,55,'Cara memasak tradisional Tidung yang sangat menonjol agar bau amis hasil laut hilang adalah banyak menggunakan perpaduan bumbu aromatik beraroma tajam dan asam segar yakni?','multiple_choice','[\"Kecap manis dan penyedap MSG banyak-banyak\",\"Jeruk nipis, asam jawa (Kamal), kunyit, sereh, dan terasi udang bakar\",\"Saus tomat botolan\",\"Mayones dan lada hitam tumbuk\"]','Jeruk nipis, asam jawa (Kamal), kunyit, sereh, dan terasi udang bakar',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(275,55,'Minuman segar atau jajanan kue cincin (Cincin Manis) berbahan gula merah khas Tidung biasa disajikan saat masyarakat mengadakan acara?','multiple_choice','[\"Gotong royong membangun rumah (Mendiami Baloy) \\/ Kumpul kerabat\",\"Berperang di laut (Ngayau lepas)\",\"Menyendiri di hutan rimbun\",\"Di pengadilan\"]','Gotong royong membangun rumah (Mendiami Baloy) / Kumpul kerabat',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(276,56,'Sambal cocol khas Tarakan untuk makan Kerang Kapah rebus agar tidak amis dan perut terasa hangat pedas umumnya terbuat dari racikan?','multiple_choice','[\"Kacang tanah giling kasar\",\"Kecap asin manis campur bawang goreng renyah\",\"Tumbukan kasar cabai rawit pedas murni, bawang, perasan jeruk nipis kuat, dan sedikit petis\\/terasi\",\"Saus keju gurih impor\"]','Tumbukan kasar cabai rawit pedas murni, bawang, perasan jeruk nipis kuat, dan sedikit petis/terasi',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(277,56,'Nasi khas suku Tidung yang sering dibawa sebagai bekal melaut atau saat festival Iraw Tengkayu, diolah dari beras campur santan mirip nasi uduk/lemak warna putih adalah nasi?','multiple_choice','[\"Nasi Liwet Solo\",\"Nasi Subut \\/ Nasi Rasul\",\"Nasi Kuning ayam\",\"Nasi Goreng merah\"]','Nasi Subut / Nasi Rasul',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(278,56,'Pencuci mulut (kue/wadai basah) dari suku Tidung yang teksturnya kenyal terbuat dari tepung beras ketan atau singkong lalu ditaburi kelapa parut asin-gurih sering disebut kue?','multiple_choice','[\"Putu Ayu dan Lapis\",\"Ongol-ongol atau Kepurun Tidung\",\"Bolu Susu\",\"Martabak manis ukuran raksasa\"]','Ongol-ongol atau Kepurun Tidung',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(279,56,'[HOTS - Analisis Sains Pangan: Kerang Kapah Rebus] Kuliner Kapah khas Tarakan dimasak dengan bumbu sederhana: hanya air, serai, jahe, dan sedikit garam tanpa minyak goreng. Analisis kuliner terhadap kesederhanaan bumbu ini membuktikan bahwa...','multiple_choice','[\"Masyarakat Tidung tidak mampu membeli rempah-rempah yang mahal\",\"Bahan baku kerang kapah yang masih sangat segar memiliki rasa manis gurih alami (asam glutamat murni) yang justru akan rusak jika ditutupi bumbu pekat yang berlebihan\",\"Kerang kapah tidak cocok dimasak dengan air mendidih\",\"Kuliner tersebut belum selesai dimasak oleh juru masak\"]','Bahan baku kerang kapah yang masih sangat segar memiliki rasa manis gurih alami (asam glutamat murni) yang justru akan rusak jika ditutupi bumbu pekat yang berlebihan','Filosofi kuliner pesisir sejati adalah \"menghormati kesegaran bahan\": rasa umami alami kapah pantai Amal sudah sempurna, jahe dan serai hanya bertindak sebagai penyeimbang aroma.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(280,56,'[HOTS - Studi Kasus Ekowisata Kuliner Berkelanjutan] Kawasan Pantai Amal Tarakan menjadi sentra warung kuliner kerang kapah rebus dan kepiting soka. Langkah mitigasi apa yang wajib diterapkan pengelola wisata agar populasi kerang kapah di pantai tidak mengalami kepunahan (overfishing)?','multiple_choice','[\"Menggunakan alat hisap pasir bermesin diesel untuk memanen kapah secara massal\",\"Menerapkan aturan ukuran minimum kerang yang boleh diambil (hanya kapah dewasa), melarang eksploitasi saat musim pemijahan, dan menjaga kelestarian hutan mangrove pesisir\",\"Menutup seluruh pantai bagi wisatawan lokal maupun mancanegara\",\"Mengganti kerang kapah dengan kerang kalengan impor dari luar negeri\"]','Menerapkan aturan ukuran minimum kerang yang boleh diambil (hanya kapah dewasa), melarang eksploitasi saat musim pemijahan, dan menjaga kelestarian hutan mangrove pesisir','Prinsip panen berkelanjutan (sustainable harvesting): mengambil kapah yang sudah matang gonad dan membiarkan kapah anakan berkembang biak menjaga keseimbangan ekologis.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(281,57,'Seni pencak silat / ilmu bela diri asli kaum laki-laki yang turun temurun dilestarikan oleh masyarakat Tidung untuk melindungi diri atau keluarga dinamakan silat?','multiple_choice','[\"Silat Cimande\",\"Silat Kuntau (Kuntau Tidung)\",\"Karate sabuk hitam\",\"Gulat gaya bebas\"]','Silat Kuntau (Kuntau Tidung)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(282,57,'Bela diri Kuntau tidak hanya fokus pada kekuatan fisik (pukul meninju musuh), tetapi lebih mengutamakan kelenturan gerak reflek tubuh menghindari serangan (elakan) serta mengandalkan serangan tipuan atau teknik?','multiple_choice','[\"Teknik Kuncian patah tulang (Bantingan kilat) dan Kuda-kuda lentur\",\"Teknik terbang layang pakai tali\",\"Bersembunyi cepat (ninja) menghilang dari pandangan musuh\",\"Menembak senapan angin dari jauh saja\"]','Teknik Kuncian patah tulang (Bantingan kilat) dan Kuda-kuda lentur',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(283,57,'Tarian penyambutan yang menggunakan alat tempur (pisau belati kembar pendek atau tanpa senjata sama sekali) dan dibawakan dua pesilat Kuntau sebelum berkelahi sering menjadi bagian persembahan saat acara adat?','multiple_choice','[\"Resepsi Pernikahan (pengantin diarak) atau penyambutan pejabat penting raja\",\"Saat warga gotong royong panen ladang\",\"Setiap kali nelayan naik perahu menangkap ikan kecil\",\"Hanya di tengah hutan sendirian sepi\"]','Resepsi Pernikahan (pengantin diarak) atau penyambutan pejabat penting raja',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(284,57,'Dalam Kuntau Tidung, busana yang sering dikenakan oleh sang pesilat adalah pakaian kebesaran Melayu Tidung lengkap yang berwarna serba?','multiple_choice','[\"Putih polisi piyama santai\",\"Hitam pekat, ikat pinggang kain (sabuk), dan celana gombrang besar (sarung pesak) ikat kepala merah \\/ Laung\",\"Seragam loreng militer darat komando Eropa Timur tebal\",\"Pakaian selam tebal basah karena pesisir air laut\"]','Hitam pekat, ikat pinggang kain (sabuk), dan celana gombrang besar (sarung pesak) ikat kepala merah / Laung',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(285,57,'Alat musik ritmis pukul apa yang mengiringi gerakan (menentukan tempo cepat-lambatnya langkah kuda-kuda dan pukulan) dari sepasang pesilat Kuntau di atas arena panggung?','multiple_choice','[\"Pukulan Gendang bedug dan Gong ketipung\",\"Suara piano klasik dari radio tua Belanda di pojok panggung\",\"Suara mulut penyanyi opera tinggi\",\"Hening murni mutlak tak bersuara agar khusyuk sakral\"]','Pukulan Gendang bedug dan Gong ketipung',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(286,58,'Penguasaan beladiri Kuntau pesisir sangat penting di zaman kerajaan (hegemoni Tidung Tarakan) di masa kuno karena berfungsi praktis sebagai?','multiple_choice','[\"Tuntutan untuk menjadi model panggung hiburan pelawak raja belaka\",\"Hanya untuk lomba 17 Agustus\",\"Pertahanan dari serangan perompak laut (bajak laut\\/lanun) dan kemampuan berduel senjata tajam di dek perahu (area sempit maritim)\",\"Tuntutan agar bisa mendaftar jadi tentara militer belanda\"]','Pertahanan dari serangan perompak laut (bajak laut/lanun) dan kemampuan berduel senjata tajam di dek perahu (area sempit maritim)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(287,58,'Guru besar atau pelatih yang menurunkan ilmu bela diri rahasia (Kuntau) secara lisan dan praktek disebut?','multiple_choice','[\"Pendekar \\/ Guru Silat Kuntau (Tuha\\/Tetua)\",\"Dosen olahraga pencak silat kampus\",\"Pelatih gym binaragawan atlet\",\"Hakim mahkamah konstitusi negara\"]','Pendekar / Guru Silat Kuntau (Tuha/Tetua)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(288,58,'Kuda-kuda dalam Kuntau pesisir Tidung cenderung?','multiple_choice','[\"Sangat tinggi berdiri kaku (kaku statis)\",\"Rendah berjongkok menyentuh tanah rebahan mutlak diam\",\"Merendah, lentur (dinamis), merunduk mengakar ke tanah bagai pohon kokoh agar sulit dibanting (Sikap Pasang)\",\"Selalu melompat-lompat tiada henti laksana kanguru sirkus\"]','Merendah, lentur (dinamis), merunduk mengakar ke tanah bagai pohon kokoh agar sulit dibanting (Sikap Pasang)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(289,58,'[HOTS - Analisis Akulturasi Seni Bela Diri Kuntau] Seni bela diri \"Kuntau\" yang berkembang di kalangan pendekar pesisir Suku Tidung dan Banjar memperlihatkan akulturasi antara teknik silat Melayu Nusantara dengan seni bela diri Kuntao asal Tiongkok selatan. Analisis historis terjadinya akulturasi beladiri ini adalah...','multiple_choice','[\"Penjajahan militer bangsa Tiongkok kuno atas pulau Tarakan\",\"Jalinan persahabatan, asimilasi, dan pertukaran ilmu bela diri antara pendekar Melayu pesisir dengan perantau Tionghoa yang telah berakulturasi damai di bandar pelabuhan maritim\",\"Kewajiban atlet silat untuk menghafal bahasa mandarin\",\"Hasil dari pertandingan tarung bebas antar suku di masa penjajahan\"]','Jalinan persahabatan, asimilasi, dan pertukaran ilmu bela diri antara pendekar Melayu pesisir dengan perantau Tionghoa yang telah berakulturasi damai di bandar pelabuhan maritim','Kuntau adalah bukti kosmopolitanisme bandar dagang: gesekan fisik beladiri bermutasi menjadi persaudaraan pendekar yang memadukan kelincahan langkah silat dan ketajaman pukulan kuntao.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(290,58,'[HOTS - Analisis Nilai Filosofis Pendekar Kuntau] Dalam sumpah adat perguruan Kuntau Tidung, seorang murid dilarang keras memulai perkelahian dan diwajibkan mengalah sebanyak tiga kali sebelum terpaksa membela diri. Nilai budi pekerti apa yang ditanamkan melalui sumpah tersebut?','multiple_choice','[\"Menunjukkan bahwa pendekar Kuntau memiliki sifat penakut dan pengecut\",\"Menegaskan bahwa bela diri sejati adalah ilmu menaklukkan hawa nafsu diri sendiri, menjaga kedamaian masyarakat, dan menggunakan kekuatan hanya demi mempertahankan kehormatan yang terancam\",\"Kewajiban melarikan diri dari medan pertempuran saat terdesak\",\"Hanya sekadar formalitas upacara penerimaan sabuk perguruan\"]','Menegaskan bahwa bela diri sejati adalah ilmu menaklukkan hawa nafsu diri sendiri, menjaga kedamaian masyarakat, dan menggunakan kekuatan hanya demi mempertahankan kehormatan yang terancam','Falsafah silat luhur: \"Musuh jangan dicari, bersua pantang dielakkan.\" Kuntau adalah seni membela diri dan menjaga marwah, bukan instrumen kekerasan dan kesombongan.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(291,59,'Bahasa suku Tidung yang diucapkan sehari-hari oleh penduduk pesisir Tarakan, Bulungan, Malinau, dan Nunukan digolongkan oleh ahli linguistik serumpun ke dalam keluarga bahasa?','multiple_choice','[\"Austronesia (Rumpun Dayak Murutik\\/Tidung Utara)\",\"Bahasa Indo-Eropa Romawi Barat klasik kuno\",\"Bahasa Sino-Tibet Mandarin\",\"Bahasa Papua (Trans-Nugini) timur murni tanpa serapan asing\"]','Austronesia (Rumpun Dayak Murutik/Tidung Utara)',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(292,59,'Karena letaknya strategis di jalur persimpangan pelayaran (perdagangan laut rempah-rempah), banyak kosa kata bahasa Tidung pesisir menyerap atau dipengaruhi amat kuat oleh kosa kata dari bahasa penghubung niaga lama (lingua franca) yaitu?','multiple_choice','[\"Bahasa Inggris gaul London\",\"Bahasa Melayu klasik (Arab Melayu) pesisir\",\"Bahasa India (Tamil) selatan\",\"Bahasa Thailand utara pegunungan es\"]','Bahasa Melayu klasik (Arab Melayu) pesisir',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(293,59,'Bentuk kesusastraan lisan (puisi bersajak) terpopuler dari Suku Tidung yang paling sering digunakan tetua adat untuk menyisipkan petuah bijak teguran jenaka atau merayu calon menantu lamaran adalah seni bertutur berbentuk?','multiple_choice','[\"Pantun (Berbalas Pantun empat baris bersajak a-b-a-b jenaka)\",\"Puisi bebas berhuruf tak rima tanpa aturan\",\"Haiku Jepang sastra tinggi kaku\",\"Menulis kaligrafi dinding semata\"]','Pantun (Berbalas Pantun empat baris bersajak a-b-a-b jenaka)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(294,59,'Kalimat sapaan/pertanyaan khas keseharian diucapkan orang Tidung Tarakan saat berjumpa kerabat untuk menanyakan \"Apa kabar? (Bagaimana kabarmu?)\" biasanya berbunyi?','multiple_choice','[\"\\\"Kopisanangan?\\\"\",\"\\\"Pian kiyapa habar?\\\"\",\"\\\"Nyo kaba?\\\"\",\"\\\"Napa kabar (Atau: Napa Ulunmu)?\\\"\"]','\"Napa kabar (Atau: Napa Ulunmu)?\"',NULL,4,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(295,59,'Tradisi memadukan bahasa kiasan perumpamaan alam yang puitis, misalnya menyebut gadis cantik dan berbudi halus laksana \"Bulan Purnama Kesiangan\" dalam pidato tetua saat perkawinan Tidung mencerminkan filosofi tingginya masyarakat dalam merawat?','multiple_choice','[\"Seni perang kasar beringas menghardik musuh tawanan\",\"Adab (kesopanan) dalam menjaga lisan dan diplomasi bermartabat tanpa melukai perasaan orang lain\",\"Kesombongan merendahkan wanita miskin\",\"Tidak ada maksud apa-apa semata karena bosan berbicara biasa\"]','Adab (kesopanan) dalam menjaga lisan dan diplomasi bermartabat tanpa melukai perasaan orang lain',NULL,5,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(296,60,'Dalam dialek Tidung kuno (sastra adat sesepuh), sebutan kehormatan (gelar) yang ditujukan kepada Raja / Sultan tertinggi keraton (Penguasa Tarakan/Tengara) adalah sapaan gelar?','multiple_choice','[\"Datuk (Datuk Amiril) \\/ Paduka\",\"Gusti pangeran\",\"Raden mas londo jawa\",\"Presiden republik pesisir samudera\"]','Datuk (Datuk Amiril) / Paduka',NULL,1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(297,60,'Seni berbalas pantun lisan pada saat rombongan pengantin pria tiba di depan pintu rumah pengantin wanita untuk memohon izin masuk meminang, sering dikenal sebagai tradisi sastra ritual?','multiple_choice','[\"Buka pintu lawang \\/ Bepantun Lamaran (Bebalai)\",\"Bertarung silat darah berdarah beringas tanpa ampun selamanya di depan pagar rumah (Kuntau mati)\",\"Membakar pintu rumah marah memaksa menerobos\",\"Diam seribu bahasa bisu membisu\"]','Buka pintu lawang / Bepantun Lamaran (Bebalai)',NULL,2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(298,60,'Kosakata \"Ulun\" dalam bahasa ibu Suku Tidung secara harafiah berarti?','multiple_choice','[\"Binatang hutan buas ganas\",\"Orang (Manusia \\/ Hamba)\",\"Sungai besar tak berujung batas samudera\",\"Makanan pokok beras kuning\"]','Orang (Manusia / Hamba)',NULL,3,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(299,60,'[HOTS - Analisis Vitalitas Bahasa Daerah Terancam Punah] Bahasa Tidung kini digolongkan sebagai bahasa daerah dengan status \"rentan\" oleh Balai Bahasa karena anak-anak muda di perkotaan Tarakan lebih memilih berbahasa Indonesia gaul. Faktor internal paling mendasar penyebab menurunnya penggunaan bahasa ibu ini adalah...','multiple_choice','[\"Bahasa Tidung memiliki kosakata yang terlalu sedikit untuk percakapan\",\"Rendahnya kebanggaan identitas kultural dan terputusnya pembiasaan komunikasi bahasa Tidung di lingkungan keluarga inti rumah tangga\",\"Adanya undang-undang pemerintah yang melarang penggunaan bahasa daerah di ruang publik\",\"Bahasa Tidung tidak dapat dituliskan menggunakan huruf latin\"]','Rendahnya kebanggaan identitas kultural dan terputusnya pembiasaan komunikasi bahasa Tidung di lingkungan keluarga inti rumah tangga','Transmisi antargenerasi (keluarga) adalah benteng utama kelestarian bahasa; ketika orang tua berhenti menuturkannya kepada anak, vitalitas bahasa daerah akan runtuh.',4,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(300,60,'[HOTS - Solusi Inovatif Revitalisasi Bahasa Tidung] Sebagai peserta didik generasi digital di Kaltara, proyek karya nyata berbasis teknologi apa yang paling efektif dan kontekstual untuk menyelamatkan peribahasa dan sastra lisan Tidung dari kepunahan?','multiple_choice','[\"Menunggu bantuan dana dari negara asing sebelum berbuat sesuatu\",\"Mengembangkan aplikasi kamus saku audio digital Tidung-Indonesia berbasis web dan memproduksi konten siniar (podcast) cerita rakyat Tidung di media sosial\",\"Menolak belajar bahasa nasional dan bahasa internasional sama sekali\",\"Mengunci buku-buku sastra Tidung kuno di lemari arsip agar tidak rusak\"]','Mengembangkan aplikasi kamus saku audio digital Tidung-Indonesia berbasis web dan memproduksi konten siniar (podcast) cerita rakyat Tidung di media sosial','Revitalisasi bahasa di era digital mengharuskan pemanfaatan kanal generasi muda: digitalisasi suara (audio lexicon) dan storytelling online menjamin keberlanjutan bahasa purba di telinga masa depan.',5,'2026-09-21 03:28:14','2026-09-21 08:49:48'),(301,61,'Berapa jumlah suku utama yang mewakili budaya Kalimantan Utara dalam media pembelajaran ini?','multiple_choice','[\"2 suku\",\"3 suku\",\"4 suku\",\"5 suku\"]','4 suku','Empat suku utama dipelajari: Dayak, Banjar, Kutai, dan Tidung—mewakili keberagaman budaya Kalimantan Utara.',1,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(302,61,'Provinsi Kalimantan Utara resmi terbentuk pada tahun berapa?','multiple_choice','[\"2008\",\"2010\",\"2012\",\"2015\"]','2012','Kalimantan Utara resmi menjadi provinsi ke-34 Indonesia pada tahun 2012, menjadikannya provinsi termuda saat itu.',2,'2026-09-21 03:28:14','2026-09-21 03:28:14'),(303,61,'Ibu kota Provinsi Kalimantan Utara adalah?','multiple_choice','[\"Tarakan\",\"Nunukan\",\"Tanjung Selor\",\"Bulungan\"]','Tanjung Selor','Tanjung Selor adalah ibu kota Provinsi Kalimantan Utara, berlokasi di Kabupaten Bulungan di tepi Sungai Kayan.',3,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(304,61,'Suku yang dikenal sebagai \"Suku Laut\" di Kalimantan Utara adalah?','multiple_choice','[\"Dayak\",\"Banjar\",\"Kutai\",\"Tidung\"]','Tidung','Suku Tidung dikenal sebagai \"Suku Laut\" karena kehidupan dan tradisi mereka sangat erat kaitannya dengan laut.',4,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(305,61,'Kerajaan kuno yang berkaitan dengan Suku Kutai di Kalimantan adalah?','multiple_choice','[\"Kerajaan Majapahit\",\"Kerajaan Kutai Martadipura\",\"Kerajaan Sriwijaya\",\"Kerajaan Banjar\"]','Kerajaan Kutai Martadipura','Kerajaan Kutai Martadipura diakui sebagai kerajaan Hindu tertua di Nusantara (sekitar abad ke-4 M), akar sejarah Suku Kutai.',5,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(306,61,'Suku yang paling banyak mendiami kawasan pedalaman dan hutan Kalimantan adalah?','multiple_choice','[\"Tidung\",\"Kutai\",\"Dayak\",\"Banjar\"]','Dayak','Suku Dayak adalah masyarakat adat yang telah lama mendiami pedalaman Kalimantan, hidup harmonis berdampingan dengan alam hutan Borneo.',6,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(307,61,'Kota terbesar di Kalimantan Utara yang juga merupakan pusat ekonomi provinsi ini adalah?','multiple_choice','[\"Tanjung Selor\",\"Nunukan\",\"Malinau\",\"Tarakan\"]','Tarakan','Tarakan adalah kota terbesar dan pusat perekonomian Kalimantan Utara, dikenal sebagai kota kepiting dan pintu masuk utama provinsi.',7,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(308,61,'Suku Banjar berasal dari Kalimantan bagian mana sebelum banyak bermigrasi ke Kalimantan Utara?','multiple_choice','[\"Kalimantan Tengah\",\"Kalimantan Selatan\",\"Kalimantan Timur\",\"Kalimantan Barat\"]','Kalimantan Selatan','Suku Banjar berasal dari Kalimantan Selatan (sekitar Banjarmasin), dan banyak bermigrasi ke Kalimantan Utara sambil membawa tradisi budaya mereka.',8,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(309,61,'Burung yang menjadi simbol kemuliaan dan keberanian bagi banyak suku di Kalimantan adalah?','multiple_choice','[\"Merak\",\"Elang Bondol\",\"Enggang (Rangkong)\",\"Merpati\"]','Enggang (Rangkong)','Burung Enggang atau Rangkong adalah simbol tertinggi di banyak suku Kalimantan, terutama Dayak. Bulunya yang indah melambangkan kemuliaan.',9,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(310,61,'Nilai budaya yang menjadi landasan kehidupan sosial semua suku di Kalimantan Utara adalah?','multiple_choice','[\"Persaingan antarkelompok\",\"Individualisme\",\"Gotong royong dan kebersamaan\",\"Isolasi budaya\"]','Gotong royong dan kebersamaan','Gotong royong dan semangat kebersamaan adalah nilai universal yang dijunjung tinggi semua suku di Kaltara, tercermin dalam setiap upacara adat.',10,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(311,62,'Festival Iraw Tengkayu digelar setiap berapa tahun sekali?','multiple_choice','[\"Setiap tahun\",\"Setiap 2 tahun\",\"Setiap 3 tahun\",\"Setiap 5 tahun\"]','Setiap 2 tahun','Festival Iraw Tengkayu diselenggarakan setiap dua tahun sekali di Tarakan, menjadi event budaya yang paling dinantikan masyarakat Kaltara.',1,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(312,62,'Filosofi hidup Suku Tidung \"Tau Sama Tau, Berat Sama Dipikul\" mencerminkan nilai?','multiple_choice','[\"Kompetisi\",\"Individualisme\",\"Gotong royong\",\"Isolasi\"]','Gotong royong','\"Tau Sama Tau, Berat Sama Dipikul\" berarti saling mengenal dan menanggung beban bersama—cerminan semangat gotong royong inti budaya Tidung.',2,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(313,62,'Dalam Festival Iraw Tengkayu, apa yang dilarung ke laut?','multiple_choice','[\"Perahu besar\",\"Makanan dan bunga sebagai sesaji\",\"Uang logam\",\"Patung leluhur\"]','Makanan dan bunga sebagai sesaji','Makanan dan bunga dilarung ke laut sebagai sesaji—persembahan kepada laut yang menjadi sumber kehidupan masyarakat Tidung.',3,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(314,62,'Tari sakral yang menjadi pembuka Festival Iraw Tengkayu disebut?','multiple_choice','[\"Tari Jepen\",\"Tari Garay\",\"Tari Hudoq\",\"Tari Kancet\"]','Tari Garay','Tari Garay adalah tarian sakral pembuka Festival Iraw Tengkayu, dibawakan untuk mengawali ritual dan memohon berkah kepada Yang Maha Kuasa.',4,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(315,62,'Festival Iraw Tengkayu biasanya diselenggarakan pada bulan?','multiple_choice','[\"Juli\",\"Agustus\",\"September\",\"Oktober\"]','Oktober','Festival Iraw Tengkayu biasanya digelar pada bulan Oktober, bertepatan dengan waktu yang dianggap baik menurut tradisi Suku Tidung.',5,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(316,62,'Filosofi Rumah Baloy sebagai rumah adat Kaltara adalah?','multiple_choice','[\"Keunggulan satu suku\",\"Kaltara Bersatu dalam Keberagaman\",\"Pemisahan budaya tiap suku\",\"Persaingan antarbudaya\"]','Kaltara Bersatu dalam Keberagaman','Rumah Baloy mewujudkan filosofi \"Kalimantan Utara Bersatu dalam Keberagaman\"—tekad bersatu meski berbeda suku dan budaya.',6,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(317,62,'Upacara pernikahan adat Banjar di Kalimantan Utara biasanya diiringi musik?','multiple_choice','[\"Gamelan Jawa\",\"Musik Panting\",\"Kecapi Sunda\",\"Angklung\"]','Musik Panting','Musik Panting adalah pengiring tradisional upacara pernikahan dan penyambutan tamu adat Banjar, sebagai tanda penghormatan tertinggi.',7,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(318,62,'Dalam tradisi Dayak Bahau, apa makna pemakaian topeng dalam Tari Hudoq?','multiple_choice','[\"Hiasan semata\",\"Penari diyakini memanifestasikan roh pelindung\",\"Agar penari tidak dikenali\",\"Mengikuti mode\"]','Penari diyakini memanifestasikan roh pelindung','Topeng dalam Tari Hudoq bukan hiasan—penari diyakini memanifestasikan roh-roh pelindung yang dimohon hadir untuk menjaga ladang.',8,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(319,62,'Mandau Pusaka dalam tradisi Dayak diperlakukan berbeda karena?','multiple_choice','[\"Lebih mahal harganya\",\"Dipercaya memiliki kekuatan spiritual dan dijaga dengan ritual\",\"Bentuknya lebih bagus\",\"Lebih tajam dari Mandau biasa\"]','Dipercaya memiliki kekuatan spiritual dan dijaga dengan ritual','Mandau Pusaka diyakini memiliki jiwa dan kekuatan magis (supranatural), harus dijaga melalui ritual khusus oleh pemilik atau tetua adat.',9,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(320,62,'Kain Sasirangan dibuat oleh Suku Banjar dengan teknik apa?','multiple_choice','[\"Tenun ATBM\",\"Ikat celup\",\"Batik tulis\",\"Bordir\"]','Ikat celup','Sasirangan dibuat dengan teknik ikat celup: kain dijahit pola tertentu, diikat, dicelup ke larutan warna, lalu ikatan dilepas menghasilkan motif khas.',10,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(321,63,'Tari Hudoq termasuk kategori tari apa?','multiple_choice','[\"Tari hiburan semata\",\"Tari ritual sakral\",\"Tari pergaulan modern\",\"Tari pertunjukan komersial\"]','Tari ritual sakral','Tari Hudoq adalah tari ritual sakral yang dilakukan untuk memohon kesuburan ladang dan perlindungan dari roh-roh alam—bukan sekadar hiburan.',1,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(322,63,'Kata \"Hudoq\" dalam bahasa Dayak Bahau berarti?','multiple_choice','[\"Roh penjaga\",\"Roh penolong\",\"Roh nenek moyang\",\"Dewa alam\"]','Roh penolong','\"Hudoq\" berarti \"roh penolong\" dalam bahasa Dayak Bahau—penari diyakini dirasuki roh-roh penolong saat melaksanakan ritual ini.',2,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(323,63,'Tari Jepen berasal dari akulturasi budaya apa?','multiple_choice','[\"Dayak dan Arab\",\"Melayu, Arab, dan lokal Kalimantan\",\"Jawa dan Melayu\",\"China dan Melayu\"]','Melayu, Arab, dan lokal Kalimantan','Tari Jepen mencerminkan akulturasi tiga budaya: Melayu (asal lokal), Arab (melalui Islam), dan lokal Kalimantan—simbol toleransi budaya.',3,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(324,63,'Gerakan Tari Jepen bercirikan apa?','multiple_choice','[\"Keras dan agresif\",\"Lembut dan anggun\",\"Cepat dan berenergi tinggi\",\"Akrobatik dan atletis\"]','Lembut dan anggun','Gerakan Tari Jepen bercirikan kelembutan dan keanggunan—mencerminkan budi pekerti halus masyarakat Kutai dan nilai-nilai keislaman.',4,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(325,63,'Alat musik utama pengiring Tari Jepen adalah?','multiple_choice','[\"Garantung dan gendang\",\"Gambus dan rebana\",\"Kecapi dan suling\",\"Biola dan panting\"]','Gambus dan rebana','Gambus (alat petik berpengaruh Arab) dan Rebana (gendang kecil) mengiringi Tari Jepen, mencerminkan akulturasi budaya Melayu-Arab.',5,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(326,63,'Tari Hudoq biasanya dilaksanakan pada saat?','multiple_choice','[\"Pesta pernikahan\",\"Tahun baru adat\",\"Musim tanam padi\",\"Upacara kematian\"]','Musim tanam padi','Tari Hudoq dilaksanakan pada musim tanam padi sebagai ritual adat memohon berkat dan perlindungan agar panen melimpah.',6,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(327,63,'Gerakan utama Tari Hudoq terinspirasi dari?','multiple_choice','[\"Harimau berburu\",\"Ikan berenang\",\"Sayap Burung Enggang\",\"Angin bertiup\"]','Sayap Burung Enggang','Gerakan utama Tari Hudoq menirukan kibasan sayap Burung Enggang yang anggun, melambangkan kebebasan jiwa dan kekuatan spiritual.',7,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(328,63,'Kostum Tari Jepen menggunakan motif apa?','multiple_choice','[\"Motif Dayak Kenyah\",\"Kain bermotif Melayu Kutai berwarna cerah\",\"Batik Jawa klasik\",\"Kain polos tanpa motif\"]','Kain bermotif Melayu Kutai berwarna cerah','Kostum Tari Jepen menggunakan kain bermotif Melayu Kutai berwarna cerah, mencerminkan kegembiraan dan kekayaan budaya Kutai.',8,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(329,63,'Tari Jepen kini diajarkan di mana sebagai upaya pelestarian?','multiple_choice','[\"Hanya di keraton\",\"Kurikulum seni budaya sekolah\",\"Hanya di komunitas adat\",\"Festival internasional saja\"]','Kurikulum seni budaya sekolah','Tari Jepen dimasukkan dalam kurikulum seni budaya sekolah agar generasi muda dapat mempelajari dan melestarikan warisan leluhur.',9,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(330,63,'Atribut terpenting yang membedakan Tari Hudoq dari tari lainnya adalah?','multiple_choice','[\"Kostum bulu-buluan\",\"Topeng kayu berukir besar\",\"Mahkota emas\",\"Pedang di tangan\"]','Topeng kayu berukir besar','Topeng kayu berukuran besar yang menggambarkan roh-roh alam adalah ciri paling khas dan unik Tari Hudoq, tidak dimiliki tarian lain.',10,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(331,64,'Alat musik utama Musik Panting terbuat dari?','multiple_choice','[\"Bambu dengan dawai sutra\",\"Kayu nangka dengan dawai rotan\",\"Kulit hewan dengan dawai nilon\",\"Logam dengan dawai baja\"]','Kayu nangka dengan dawai rotan','Alat musik Panting dibuat dari kayu nangka (resonansi baik) dengan dawai rotan yang ditipiskan, menghasilkan suara khas dan merdu.',1,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(332,64,'Musik Panting mulai berkembang sejak abad berapa?','multiple_choice','[\"Abad ke-15\",\"Abad ke-16\",\"Abad ke-17\",\"Abad ke-18\"]','Abad ke-17','Musik Panting berkembang sejak abad ke-17 bersamaan dengan kejayaan Kesultanan Banjar—bukti kedalaman sejarah warisan budaya ini.',2,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(333,64,'Kata \"Jepen\" berasal dari kata \"Japin\" yang berarti?','multiple_choice','[\"Jipen (nama sungai)\",\"Jenis tarian Melayu-Arab\",\"Japen (alat tenun)\",\"Jipan (nama baju adat)\"]','Jenis tarian Melayu-Arab','\"Japin\" adalah istilah untuk jenis tarian Melayu-Arab, mencerminkan akulturasi budaya Melayu lokal dengan pengaruh Islam dari pedagang Arab.',3,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(334,64,'Alat perkusi dari kuningan dalam ensambel Musik Panting disebut?','multiple_choice','[\"Babun\",\"Kangkung\",\"Tawak-tawak\",\"Garantung\"]','Kangkung','Kangkung adalah alat perkusi dari kuningan dalam ensambel Musik Panting yang memberikan warna ritmis khas dalam harmoni musik Banjar.',4,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(335,64,'Karakter suara Musik Panting digambarkan sebagai?','multiple_choice','[\"Keras dan menggelegar\",\"Dingin dan misterius\",\"Hangat dan menyentuh hati\",\"Cepat dan ritmis saja\"]','Hangat dan menyentuh hati','Suara Musik Panting yang hangat dan menyentuh hati adalah ekspresi jiwa Banjar yang penuh perasaan dan kecintaan pada tradisi leluhur.',5,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(336,64,'Instrumen modern yang ditambahkan dalam Musik Panting adalah?','multiple_choice','[\"Gitar elektrik\",\"Piano\",\"Biola\",\"Saxophone\"]','Biola','Biola ditambahkan ke ensambel Musik Panting untuk memperkaya warna melodi tanpa meninggalkan karakter tradisionalnya yang khas.',6,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(337,64,'Gendang kecil dalam ensambel Musik Panting disebut?','multiple_choice','[\"Babun\",\"Rebana\",\"Bedug\",\"Ketipung\"]','Babun','Babun adalah gendang kecil dalam ensambel Musik Panting yang berperan penting mengatur ritme dan tempo permainan musik.',7,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(338,64,'Alat musik pengiring utama Tari Hudoq adalah?','multiple_choice','[\"Rebana\",\"Gamelan\",\"Garantung\",\"Serunai\"]','Garantung','Garantung adalah alat musik perkusi logam (mirip gong) yang menjadi pengiring utama Tari Hudoq dalam setiap ritual adat Dayak.',8,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(339,64,'Musik Panting umumnya mengiringi?','multiple_choice','[\"Upacara kematian\",\"Syair puisi Melayu dan cerita rakyat\",\"Olahraga tradisional\",\"Ritual pertanian padi\"]','Syair puisi Melayu dan cerita rakyat','Musik Panting tradisionalnya mengiringi syair-syair puisi Melayu dan penceritaan kisah rakyat, sebagai media komunikasi budaya yang kaya makna.',9,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(340,64,'Keunikan Musik Panting terletak pada?','multiple_choice','[\"Suara keras yang memekakkan\",\"Perpaduan melodi pentatonik Melayu dengan ritme lincah\",\"Irama yang sangat lambat\",\"Hanya menggunakan alat tiup\"]','Perpaduan melodi pentatonik Melayu dengan ritme lincah','Perpaduan melodi pentatonik Melayu yang mengalun indah dengan ritme lincah dan dinamis menjadikan Musik Panting mudah dikenali dan khas.',10,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(341,65,'Kota Tarakan dijuluki sebagai?','multiple_choice','[\"Kota Seribu Sungai\",\"Kota Kepiting\",\"Kota Melayu Sejati\",\"Kota Borneo\"]','Kota Kepiting','Tarakan dijuluki \"Kota Kepiting\" karena merupakan penghasil kepiting soka terbesar di Indonesia, menjadikan kepiting ikon kuliner kota ini.',1,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(342,65,'Amplang adalah kerupuk yang terbuat dari?','multiple_choice','[\"Singkong\",\"Ikan pipih atau ikan tenggiri\",\"Udang vannamei\",\"Tepung terigu murni\"]','Ikan pipih atau ikan tenggiri','Amplang dibuat dari daging ikan pipih atau tenggiri yang dihaluskan, dicampur tepung sagu, dan digoreng hingga renyah mengembang.',2,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(343,65,'Bahan utama anyaman yang paling umum di Kalimantan Utara adalah?','multiple_choice','[\"Bambu\",\"Rotan\",\"Pandan\",\"Daun kelapa\"]','Rotan','Rotan adalah bahan anyaman paling umum di Kaltara—tumbuh subur di hutan Kalimantan dan dikenal karena kekuatan serta fleksibilitasnya.',3,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(344,65,'Tenun Ulap Doyo terbuat dari serat?','multiple_choice','[\"Kapas\",\"Sutra alam\",\"Tanaman doyo\",\"Serat nilon\"]','Tanaman doyo','Tenun Ulap Doyo menggunakan serat dari tanaman doyo (Curculigo latifolia), tanaman endemik Kalimantan yang daunnya dipintal menjadi benang tenun.',4,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(345,65,'Motif dalam ukiran Dayak yang melambangkan kebebasan dan kemuliaan adalah?','multiple_choice','[\"Motif naga\",\"Motif bunga teratai\",\"Motif Burung Enggang\",\"Motif ikan arwana\"]','Motif Burung Enggang','Motif Burung Enggang paling ikonik dalam seni Dayak—melambangkan kebebasan, keberanian, dan kemuliaan yang dijunjung tinggi masyarakat Kalimantan.',5,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(346,65,'Kepiting Soka dipanen saat dalam kondisi?','multiple_choice','[\"Sedang bertelur\",\"Baru selesai berganti cangkang\",\"Ukuran paling besar\",\"Musim migrasi\"]','Baru selesai berganti cangkang','Kepiting Soka dipanen saat molting—baru berganti cangkang. Saat itu seluruh tubuh masih lunak sehingga bisa dimakan utuh termasuk cangkangnya.',6,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(347,65,'Material utama pembuatan Rumah Baloy adalah?','multiple_choice','[\"Kayu meranti\",\"Bambu pilihan\",\"Kayu ulin (kayu besi)\",\"Beton bertulang\"]','Kayu ulin (kayu besi)','Kayu ulin (kayu besi) adalah material utama Rumah Baloy—kayu asli Kalimantan yang kuat, tahan rayap, dan dapat bertahan ratusan tahun.',7,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(348,65,'Kalimantan Utara terkenal sebagai penghasil terbesar?','multiple_choice','[\"Kelapa sawit\",\"Karet alam\",\"Rumput laut\",\"Kopi Arabika\"]','Rumput laut','Kalimantan Utara, terutama Tarakan, adalah penghasil rumput laut terbesar Indonesia. Kondisi perairan ideal menjadikannya sentra budidaya nasional.',8,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(349,65,'Teknik pembuatan kain Sasirangan adalah?','multiple_choice','[\"Batik tulis tangan\",\"Tenun ikat tradisional\",\"Ikat celup\",\"Bordir mesin\"]','Ikat celup','Sasirangan dibuat dengan teknik ikat celup: dijahit pola tertentu, diikat, dicelup warna, lalu ikatan dilepas—menghasilkan motif khas Banjar.',9,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(350,65,'Tas anyaman rotan bermotif geometris bernilai tinggi dari Kaltara disebut?','multiple_choice','[\"Tas Doyo\",\"Tas Belida\",\"Tas Sugu\",\"Tas Enggang\"]','Tas Belida','Tas Belida adalah tas anyaman rotan bermotif geometris bernilai tinggi khas Kaltara. Keunikan motifnya yang rumit menjadikannya karya seni premium.',10,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(351,66,'Suku Dayak Bahau mendiami wilayah utama di?','multiple_choice','[\"Pesisir pantai\",\"Kawasan pedalaman Kalimantan\",\"Pulau-pulau kecil\",\"Dataran rendah\"]','Kawasan pedalaman Kalimantan','Suku Dayak Bahau mendiami kawasan pedalaman Kalimantan, jauh dari pesisir, hidup berdampingan dengan alam hutan Borneo yang kaya.',1,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(352,66,'Tari Hudoq merupakan tarian yang berfungsi sebagai?','multiple_choice','[\"Hiburan masyarakat semata\",\"Ritual sakral memohon kesuburan ladang\",\"Pertunjukan wisata komersial\",\"Olahraga tradisional\"]','Ritual sakral memohon kesuburan ladang','Tari Hudoq berfungsi sebagai ritual sakral memohon kesuburan ladang—penari bertopeng dipercaya mengundang roh pelindung untuk menjaga tanaman.',2,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(353,66,'Kostum penari Hudoq terbuat dari bahan alami berupa?','multiple_choice','[\"Kulit binatang dan bulu burung\",\"Daun pisang dan rotan\",\"Kain sutra bordir\",\"Bahan sintetis modern\"]','Daun pisang dan rotan','Kostum Tari Hudoq dibuat dari daun pisang yang dianyam dan rotan—bahan alami yang mencerminkan kedekatan Dayak Bahau dengan alam.',3,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(354,66,'Kata \"Hudoq\" dalam bahasa Dayak Bahau bermakna?','multiple_choice','[\"Semangat perang\",\"Roh penolong\",\"Panen berlimpah\",\"Doa keselamatan\"]','Roh penolong','\"Hudoq\" berarti \"roh penolong\"—penari diyakini dirasuki roh-roh penolong yang datang melindungi ladang masyarakat Dayak Bahau.',4,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(355,66,'Tari Hudoq kini juga dipentaskan di luar upacara adat, yaitu di?','multiple_choice','[\"Gedung pemerintahan\",\"Festival budaya dan acara pariwisata\",\"Tempat ibadah\",\"Sekolah dasar\"]','Festival budaya dan acara pariwisata','Di era modern, Tari Hudoq dipentaskan di festival budaya dan pariwisata untuk memperkenalkan warisan Dayak kepada dunia yang lebih luas.',5,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(356,66,'Musik Panting berasal dari Suku?','multiple_choice','[\"Dayak\",\"Tidung\",\"Kutai\",\"Banjar\"]','Banjar','Musik Panting adalah kesenian musik tradisional milik Suku Banjar dari Kalimantan Selatan yang juga berkembang di Kalimantan Utara.',6,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(357,66,'Instrumen utama Musik Panting terbuat dari kayu?','multiple_choice','[\"Kayu ulin\",\"Kayu nangka\",\"Kayu meranti\",\"Kayu jati\"]','Kayu nangka','Alat musik Panting terbuat dari kayu nangka karena resonansinya sangat baik, menghasilkan suara yang khas dan merdu.',7,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(358,66,'Peran gendang Babun dalam Musik Panting adalah?','multiple_choice','[\"Instrumen melodi\",\"Instrumen harmoni latar\",\"Mengatur ritme dan tempo\",\"Improvisasi bebas\"]','Mengatur ritme dan tempo','Babun (gendang kecil) berperan penting mengatur ritme dan tempo dalam ensambel Musik Panting, menjaga kekompakan permainan.',8,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(359,66,'Musik Panting paling sering ditampilkan dalam acara?','multiple_choice','[\"Upacara kematian dan perpisahan\",\"Upacara pernikahan dan penyambutan tamu\",\"Ritual pertanian\",\"Perayaan tahun baru\"]','Upacara pernikahan dan penyambutan tamu','Musik Panting secara tradisional dimainkan dalam upacara pernikahan adat Banjar dan penyambutan tamu kehormatan sebagai penghormatan tertinggi.',9,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(360,66,'Tari Jepen merupakan warisan akulturasi budaya antara?','multiple_choice','[\"Dayak dan Jawa\",\"Melayu dan Arab\",\"China dan Melayu\",\"India dan Dayak\"]','Melayu dan Arab','Tari Jepen merupakan perpaduan budaya Melayu Kalimantan dan pengaruh Arab yang masuk melalui jalur perdagangan dan penyebaran Islam.',10,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(361,66,'\"Jepen\" berasal dari kata \"Japin\" yang merupakan istilah untuk?','multiple_choice','[\"Ritual pertanian kuno\",\"Senjata tradisional\",\"Jenis tarian Melayu-Arab\",\"Alat musik petik\"]','Jenis tarian Melayu-Arab','\"Japin\" adalah istilah untuk jenis tarian Melayu-Arab, mencerminkan masuknya pengaruh Arab ke budaya Melayu Kalimantan melalui Islam.',11,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(362,66,'Alat musik yang mencerminkan pengaruh Arab dalam Tari Jepen adalah?','multiple_choice','[\"Suling bambu\",\"Gamelan bronze\",\"Gambus\",\"Garantung gong\"]','Gambus','Gambus adalah alat musik petik bertangkai panjang berpengaruh Arab yang menjadi salah satu pengiring utama Tari Jepen.',12,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(363,66,'Tari Jepen pada umumnya dibawakan oleh?','multiple_choice','[\"Penari laki-laki tunggal\",\"Penari perempuan dalam kelompok\",\"Pasangan campuran\",\"Anak-anak\"]','Penari perempuan dalam kelompok','Tari Jepen biasanya dibawakan penari perempuan dalam kelompok dengan gerakan serasi, menggambarkan keanggunan perempuan Kutai.',13,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(364,66,'Gerakan Tari Hudoq yang paling ikonik meniru?','multiple_choice','[\"Harimau memangsa\",\"Sayap Burung Enggang\",\"Ombak lautan\",\"Angin ribut\"]','Sayap Burung Enggang','Gerakan paling ikonik Tari Hudoq menirukan kibasan sayap Burung Enggang yang lebar dan anggun—simbol kebebasan dan kekuatan spiritual.',14,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(365,66,'Nilai yang terkandung dalam Tari Jepen bagi masyarakat Kutai adalah?','multiple_choice','[\"Keberanian dalam perang\",\"Kehalusan budi pekerti dan kebersamaan\",\"Kekuatan fisik\",\"Kecepatan berlari\"]','Kehalusan budi pekerti dan kebersamaan','Tari Jepen mengekspresikan kehalusan budi pekerti dan semangat kebersamaan—nilai-nilai inti yang dijunjung tinggi dalam kehidupan sosial Kutai.',15,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(366,66,'Alat musik Garantung adalah instrumen jenis?','multiple_choice','[\"Alat musik tiup\",\"Alat musik gesek\",\"Alat musik perkusi dari logam\",\"Alat musik petik\"]','Alat musik perkusi dari logam','Garantung adalah instrumen perkusi logam mirip gong yang digunakan dalam ritual-ritual Dayak, termasuk sebagai pengiring Tari Hudoq.',16,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(367,66,'Ciri khas kostum Tari Jepen adalah penggunaan?','multiple_choice','[\"Bulu Enggang warna-warni\",\"Topeng kayu ukiran\",\"Kain bermotif Melayu Kutai berwarna cerah\",\"Pakaian serba hitam\"]','Kain bermotif Melayu Kutai berwarna cerah','Kain bermotif Melayu Kutai dengan warna cerah dan meriah adalah ciri khas kostum Tari Jepen, mencerminkan kegembiraan budaya Kutai.',17,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(368,66,'Topeng dalam Tari Hudoq menggambarkan?','multiple_choice','[\"Binatang buas hutan\",\"Wajah roh-roh alam\",\"Leluhur yang telah meninggal\",\"Dewa matahari\"]','Wajah roh-roh alam','Topeng Tari Hudoq menggambarkan wajah roh-roh alam yang dipercaya memiliki kekuatan menjaga dan menyuburkan ladang masyarakat Dayak.',18,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(369,66,'Keunikan Musik Panting dibandingkan musik tradisional lainnya adalah?','multiple_choice','[\"Hanya menggunakan satu instrumen\",\"Perpaduan melodi pentatonik Melayu dengan ritme lincah\",\"Dimainkan saat subuh\",\"Menggunakan tangga nada diatonis penuh\"]','Perpaduan melodi pentatonik Melayu dengan ritme lincah','Keunikan Musik Panting adalah perpaduan melodi pentatonik Melayu yang indah dengan ritme yang lincah dan dinamis—khas dan mudah dikenali.',19,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(370,66,'Tari Jepen kini dimasukkan dalam kurikulum sekolah dengan tujuan?','multiple_choice','[\"Menggantikan tari modern\",\"Pelestarian warisan budaya bagi generasi muda\",\"Kewajiban ujian nasional\",\"Promosi pariwisata internasional\"]','Pelestarian warisan budaya bagi generasi muda','Tari Jepen masuk kurikulum sekolah agar generasi muda dapat mempelajari, menghargai, dan melestarikan warisan budaya leluhur Kutai.',20,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(371,67,'Berapa jumlah suku utama yang dipelajari dalam media Seni Budaya Kaltara ini?','multiple_choice','[\"3\",\"4\",\"5\",\"6\"]','4','Empat suku utama dipelajari: Dayak, Banjar, Kutai, dan Tidung—representasi keberagaman budaya Kalimantan Utara.',1,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(372,67,'Tari ritual sakral milik Suku Dayak yang dilakukan saat musim tanam padi adalah?','multiple_choice','[\"Tari Jepen\",\"Tari Kancet\",\"Tari Hudoq\",\"Tari Garay\"]','Tari Hudoq','Tari Hudoq adalah ritual sakral Dayak Bahau yang dilaksanakan saat musim tanam padi untuk memohon kesuburan dan perlindungan ladang.',2,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(373,67,'Musik tradisional petik khas Suku Banjar adalah?','multiple_choice','[\"Garantung\",\"Kecapi Banjar\",\"Musik Panting\",\"Babun\"]','Musik Panting','Musik Panting adalah kesenian musik tradisional khas Suku Banjar, menggunakan alat musik petik bernama Panting sebagai instrumen utama.',3,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(374,67,'Festival laut khas Suku Tidung di Tarakan adalah?','multiple_choice','[\"Festival Erau\",\"Festival Iraw Tengkayu\",\"Festival Gawai\",\"Festival Hudoq\"]','Festival Iraw Tengkayu','Festival Iraw Tengkayu adalah festival budaya kebanggaan Suku Tidung—perayaan di atas air sebagai bentuk syukur atas rezeki laut.',4,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(375,67,'Tarian anggun Suku Kutai yang berakar budaya Melayu-Arab adalah?','multiple_choice','[\"Tari Hudoq\",\"Tari Jepen\",\"Tari Gantar\",\"Tari Garay\"]','Tari Jepen','Tari Jepen adalah tarian khas Suku Kutai hasil akulturasi budaya Melayu dan Arab, dibawakan dengan gerakan lembut dan anggun.',5,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(376,67,'Rumah adat resmi Provinsi Kalimantan Utara bernama?','multiple_choice','[\"Rumah Lamin\",\"Rumah Betang\",\"Rumah Baloy\",\"Rumah Banjar\"]','Rumah Baloy','Rumah Baloy ditetapkan sebagai rumah adat resmi Provinsi Kalimantan Utara, mencerminkan persatuan keempat suku utama dalam satu simbol arsitektur.',6,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(377,67,'Senjata tradisional ikonik Suku Dayak adalah?','multiple_choice','[\"Rencong\",\"Keris\",\"Badik\",\"Mandau\"]','Mandau','Mandau adalah senjata tradisional ikonik Suku Dayak berupa parang panjang, sekaligus identitas budaya yang dihormati dan dianggap memiliki kekuatan spiritual.',7,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(378,67,'Kain tradisional Suku Banjar yang dibuat dengan teknik ikat celup adalah?','multiple_choice','[\"Ulos\",\"Lurik\",\"Sasirangan\",\"Tenun Doyo\"]','Sasirangan','Kain Sasirangan khas Banjar dibuat dengan teknik ikat celup—kain dijahit pola tertentu, diikat, dicelup warna, menghasilkan motif yang khas.',8,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(379,67,'Kuliner khas Tarakan yang merupakan kerupuk ikan Kalimantan adalah?','multiple_choice','[\"Emping\",\"Amplang\",\"Kerupuk Udang\",\"Opak\"]','Amplang','Amplang adalah kerupuk ikan khas Kalimantan dari ikan pipih atau tenggiri—cemilan ikonik yang menjadi oleh-oleh favorit dari Tarakan.',9,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(380,67,'Tenun yang menggunakan serat tanaman endemik Kalimantan disebut Tenun?','multiple_choice','[\"Sasirangan\",\"Ulap Doyo\",\"Gringsing\",\"Songket\"]','Ulap Doyo','Tenun Ulap Doyo menggunakan serat dari tanaman doyo (Curculigo latifolia), tanaman endemik Kalimantan yang daunnya dipintal menjadi benang tenun.',10,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(381,67,'Topeng Tari Hudoq menggambarkan?','multiple_choice','[\"Dewa-dewa langit\",\"Wajah roh-roh alam\",\"Pahlawan perang\",\"Leluhur kerajaan\"]','Wajah roh-roh alam','Topeng Tari Hudoq menggambarkan wajah roh-roh alam yang dipercaya memiliki kekuatan menjaga dan menyuburkan ladang masyarakat Dayak.',11,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(382,67,'Arti nama \"Iraw Tengkayu\" dalam bahasa Tidung adalah?','multiple_choice','[\"Laut biru\",\"Pesta di atas air\",\"Nelayan bersatu\",\"Lautan rezeki\"]','Pesta di atas air','\"Iraw Tengkayu\" berarti \"pesta di atas air\"—menggambarkan perayaan di laut sebagai simbol rasa syukur masyarakat Tidung atas rezeki laut.',12,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(383,67,'Material utama Rumah Baloy yang tahan rayap adalah?','multiple_choice','[\"Kayu jati\",\"Kayu meranti\",\"Kayu ulin (besi)\",\"Kayu kelapa\"]','Kayu ulin (besi)','Kayu ulin (kayu besi) khas Kalimantan sangat tahan rayap dan dapat bertahan ratusan tahun—pilihan ideal untuk bangunan adat Rumah Baloy.',13,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(384,67,'Burung simbol kemuliaan yang sering muncul dalam motif ukiran Dayak adalah?','multiple_choice','[\"Merak\",\"Elang\",\"Enggang (Rangkong)\",\"Kakaktua\"]','Enggang (Rangkong)','Burung Enggang atau Rangkong adalah simbol kemuliaan, kebebasan, dan keberanian yang paling dihormati di Kalimantan, terutama oleh Suku Dayak.',14,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(385,67,'Sarung Mandau disebut?','multiple_choice','[\"Hulu\",\"Kumpang\",\"Pisau Raut\",\"Lamin\"]','Kumpang','Kumpang adalah sarung atau wadah Mandau, biasanya terbuat dari kayu yang diukir indah—sekaligus media ekspresi seni ukir Dayak.',15,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(386,67,'Festival Iraw Tengkayu diselenggarakan setiap?','multiple_choice','[\"Setiap tahun\",\"Setiap 2 tahun\",\"Setiap 3 tahun\",\"Setiap 5 tahun\"]','Setiap 2 tahun','Festival Iraw Tengkayu digelar setiap dua tahun sekali di Tarakan, menjadikannya event budaya yang paling dinantikan masyarakat Kaltara.',16,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(387,67,'\"Jepen\" berasal dari kata \"Japin\" yang berarti?','multiple_choice','[\"Semangat pemuda Melayu\",\"Jenis tarian Melayu-Arab\",\"Alat musik tradisional\",\"Ritual air sungai\"]','Jenis tarian Melayu-Arab','\"Japin\" adalah istilah untuk jenis tarian Melayu-Arab, mencerminkan akulturasi budaya Melayu Kalimantan dengan pengaruh Islam dari pedagang Arab.',17,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(388,67,'Filosofi \"Kalimantan Utara Bersatu dalam Keberagaman\" tercermin dalam?','multiple_choice','[\"Festival Iraw Tengkayu\",\"Mandau Pusaka\",\"Rumah Baloy\",\"Tari Hudoq\"]','Rumah Baloy','Rumah Baloy mewujudkan filosofi persatuan Kaltara—memadukan unsur arsitektur 4 suku utama (Dayak, Banjar, Kutai, Tidung) dalam satu bangunan.',18,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(389,67,'Pangan khas yang dipanen saat kepiting baru berganti cangkang adalah?','multiple_choice','[\"Amplang\",\"Kepiting Soka\",\"Ikan Pipih\",\"Dodol Rumput Laut\"]','Kepiting Soka','Kepiting Soka dipanen saat molting (baru berganti cangkang). Saat itu cangkangnya masih lunak sehingga bisa dimakan utuh—keistimewaan khas Tarakan.',19,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(390,67,'Motif sulur pakis dalam tenun Kaltara melambangkan?','multiple_choice','[\"Kekuatan perang\",\"Pertumbuhan dan kesuburan\",\"Duka cita\",\"Kematian\"]','Pertumbuhan dan kesuburan','Motif sulur pakis melambangkan pertumbuhan, kesuburan, dan kehidupan yang terus berkembang—harapan masyarakat untuk tumbuh selaras dengan alam.',20,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(391,67,'Teknik pembuatan bilah Mandau menggunakan?','multiple_choice','[\"Cetakan tuang logam\",\"Teknik tempa tradisional\",\"Mesin CNC modern\",\"Pengecoran baja\"]','Teknik tempa tradisional','Bilah Mandau dibuat dengan teknik tempa tradisional—logam dipanaskan dan dipukul berulang oleh pandai besi hingga terbentuk bilah yang kuat.',21,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(392,67,'Alat musik Babun dalam Musik Panting berfungsi sebagai?','multiple_choice','[\"Instrumen melodi utama\",\"Instrumen harmoni latar\",\"Instrumen pengatur ritme\",\"Instrumen bass\"]','Instrumen pengatur ritme','Babun (gendang kecil) berperan sebagai instrumen pengatur ritme dan tempo dalam ensambel Musik Panting, menjaga kekompakan permainan.',22,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(393,67,'Tari Jepen dibawakan sebagai ekspresi nilai?','multiple_choice','[\"Keberanian dalam perang\",\"Kehalusan budi pekerti dan kebersamaan\",\"Kekuatan magis\",\"Duka cita\"]','Kehalusan budi pekerti dan kebersamaan','Tari Jepen mengekspresikan kehalusan budi pekerti dan semangat kebersamaan—nilai inti kehidupan sosial masyarakat Kutai yang dijunjung tinggi.',23,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(394,67,'Ruang utama Rumah Baloy yang digunakan untuk pertemuan adat disebut?','multiple_choice','[\"Dapur adat\",\"Lamin\",\"Beranda utama\",\"Balai pertemuan\"]','Lamin','Lamin adalah aula besar (ruang utama) Rumah Baloy tempat pertemuan adat, musyawarah, dan upacara-upacara penting dilangsungkan.',24,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(395,67,'Bahan pewarna alami biru pada tenun tradisional berasal dari?','multiple_choice','[\"Kunyit\",\"Indigo\",\"Daun pandan\",\"Akar kayu\"]','Indigo','Tanaman Indigo (Indigofera tinctoria) menghasilkan zat warna biru alami yang tahan lama dan aman lingkungan untuk pewarnaan tenun tradisional.',25,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(396,67,'Kalimantan Utara menjadi penghasil terbesar komoditas laut berupa?','multiple_choice','[\"Ikan tuna\",\"Udang vaname\",\"Rumput laut\",\"Kepiting bakau\"]','Rumput laut','Kalimantan Utara adalah penghasil rumput laut terbesar Indonesia. Kondisi perairan yang ideal menjadikannya sentra budidaya rumput laut nasional.',26,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(397,67,'Pengukir ahli dalam tradisi Dayak disebut?','multiple_choice','[\"Mangkutak\",\"Babun\",\"Kumpang\",\"Lamin\"]','Mangkutak','Mangkutak adalah sebutan untuk pengukir ahli dalam tradisi Dayak—profesi yang sangat dihormati karena kemampuan seni ukir bermakna spiritual.',27,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(398,67,'Tas anyaman rotan bermotif geometris khas Kaltara bernilai tinggi disebut?','multiple_choice','[\"Tas Doyo\",\"Tas Enggang\",\"Tas Belida\",\"Tas Sugu\"]','Tas Belida','Tas Belida adalah tas anyaman rotan bermotif geometris yang bernilai tinggi dari Kaltara. Kerumitan motifnya menjadikannya karya seni premium.',28,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(399,67,'Motif Naga dalam ukiran Kalimantan bermakna sebagai?','multiple_choice','[\"Penguasa langit\",\"Penjaga alam bawah dan pembawa kemakmuran\",\"Dewa perang\",\"Roh kesuburan tanaman\"]','Penjaga alam bawah dan pembawa kemakmuran','Motif Naga bermakna penjaga alam bawah (laut/sungai) dan pembawa kemakmuran bagi masyarakat yang hidup di sekitar perairan Kalimantan.',29,'2026-09-21 03:28:15','2026-09-21 03:28:15'),(400,67,'Semua aspek seni budaya Kalimantan Utara pada dasarnya mencerminkan?','multiple_choice','[\"Kemajuan teknologi modern\",\"Hubungan harmonis manusia dengan alam dan nilai luhur leluhur\",\"Pengaruh dominan budaya asing\",\"Persaingan antarkelompok etnis\"]','Hubungan harmonis manusia dengan alam dan nilai luhur leluhur','Seluruh seni budaya Kaltara—tari, musik, arsitektur, kerajinan, kuliner—mencerminkan hubungan harmonis manusia dengan alam dan nilai-nilai luhur yang diwariskan turun-temurun.',30,'2026-09-21 03:28:15','2026-09-21 03:28:15');
