  `title` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `material_id` bigint(20) unsigned DEFAULT NULL,
  `teacher_id` bigint(20) unsigned NOT NULL,
  `quiz_type` enum('pretest','posttest','ujian_harian','uts','uas','standalone') NOT NULL DEFAULT 'standalone',
  `passing_score` tinyint(3) unsigned NOT NULL DEFAULT 70,
  `time_limit` smallint(5) unsigned DEFAULT NULL,
  `min_harian_required` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `quizzes_material_id_foreign` (`material_id`),
  KEY `quizzes_teacher_id_foreign` (`teacher_id`),
  CONSTRAINT `quizzes_material_id_foreign` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`) ON DELETE SET NULL,
  CONSTRAINT `quizzes_teacher_id_foreign` FOREIGN KEY (`teacher_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
